(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Coucou ! Appa a repris des forces !"},{"a":"atlab_aang","t":"Ça veut dire... que c’est l’heure des adieux..."},{"a":"atlab_sokka","t":"Fais pas cette tête ! On peut revenir quand on veut !"},{"a":"atlab_aang","t":"C’est vrai ! Tu te rappelles la route, Sokka ?"},{"a":"atlab_sokka","t":"Euh... J’ai pas trop fait attention..."},{"a":"atlab_sokka","t":"... Enfin bref ! On a des affaires ultra importantes qui nous attendent, des affaires d’Avatar !"},{"a":"atlab_sokka","t":"Allez, Momo ! On y va !"},{"a":"atlab_aang","t":"Momo ! Momo ?"},{"a":"atlab_aang","t":"Tu te plais bien ici, hein ? Bon, j’ai compris."},{"a":"atlab_aang","t":"Dites, vous voudriez bien nous le garder un petit moment ?"},{"a":"atlab_aang","t":"Je reviendrai te chercher plus tard, Momo. Promis !"},{"a":"atlab_aang","t":"Allons-y, Sokka. Merci pour tout ! Elle est super, votre boutique !"},{"a":"atlab_sokka","t":"Au revoir !"},{"a":"atlab_aang","t":"Viens, Appa ! Hop !"}]},{"id":"atlab_aang_01","i":1,"title":"Le bon mauvais chemin","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"inn","t":"Attends, gamin, j’ai pas tout compris. Tu peux reprendre depuis le début ?"},{"a":"atlab_aang","t":"Pardon ! Je récapitule !"},{"a":"atlab_aang","t":"Moi c’est Aang, l’Avatar."},{"a":"atlab_aang","t":"Mes amis et moi, on voyageait sur mon bison volant..."},{"a":"atlab_aang","t":"Et en cours de route, on a dû prendre le mauvais chemin, vu qu’on s’est retrouvés ici !"},{"a":"inn","t":"Cet énorme bestiau dehors ? Il VOLE ?"},{"a":"atlab_aang","t":"Eh oui ! Son nom est Appa. Il est très gentil !"},{"a":"inn","t":"Gentil, mais complètement vanné, à ce que je vois. Vous êtes pourchassés par quelqu’un, c’est bien ça ?"},{"a":"atlab_aang","t":"Oh, euh..."},{"a":"inn","t":"Ne vous inquiétez pas. Personne ne touchera à un cheveu de mes hôtes. Parole d’Oscar."},{"a":"inn","t":"Écoutez, ça vous dirait de séjourner ici gratuitement ?"},{"a":"atlab_aang","t":"Gratuitement ? Vous êtes sérieux ?"},{"a":"inn","t":"De toute façon, personne ne voudra de votre argent bizarre par ici."},{"a":"inn","t":"Je ne vais pas laisser une bande de garnements dormir dans la rue, quand même."},{"a":"atlab_aang","t":"M-Merci, M. Oscar !"},{"a":"inn","t":"Vous avez l’air futés. Une de mes connaissances tient une boutique, vous pourriez l’aider en échange ?"},{"a":"atlab_aang","t":"Sans problème ! Merci infiniment !"}]},{"id":"atlab_aang_02","i":2,"title":"La maîtrise du feu ?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"inn","t":"Lilu ! Viens donc voir qui est là !"},{"a":"lilu","t":"Salut ! Je n’avais encore jamais vu un tatouage pareil..."},{"a":"atlab_aang","t":"Je m’appelle Aang ! Et je peux en dire autant de votre chapeau !"},{"a":"inn","t":"Vas-y, Aang, montre-lui ton petit numéro !"},{"a":"atlab_aang","t":"Quoi, ça ?"},{"a":"lilu","t":"C-Comment tu as fait ? Je n’ai pas senti de magie à l’œuvre !"},{"a":"atlab_aang","t":"Je suis maître de l’air ! Et de la terre, et de l’eau !"},{"a":"lilu","t":"Incroyable ! Une seconde, je prends des notes..."},{"a":"lilu","t":"Du Chi, peut-être ? Je n’avais jamais rien vu de tel..."},{"a":"atlab_aang","t":"C’est ça ! Mais ce n’est pas donné à tout le monde : il faut naître avec un don et apprendre à le maîtriser."},{"a":"lilu","t":"Tu prétends être maître de l’air, de la terre et de l’eau. Pas du feu ?"},{"a":"atlab_aang","t":"Ah... J’ai... encore du travail de ce côté-là..."},{"a":"atlab_aang","t":"J’ai eu du mal à trouver un maître du feu qui veuille bien me prendre pour disciple."},{"a":"lilu","t":"Vraiment ? Je connais un peu de magie du feu !"},{"a":"lilu","t":"Ce n’est pas tout à fait pareil, mais je peux te montrer, si ça t’intéresse."},{"a":"atlab_aang","t":"Euh... avec plaisir. Merci, Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"Le dernier maître de l’air","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"elderowen","t":"Aang, mon garçon. La vie citadine te plaît ?"},{"a":"atlab_aang","t":"Owen l’ancien ! Merci de votre hospitalité."},{"a":"elderowen","t":"Inutile de me remercier. Mais dis-moi, mon garçon, où sont tes parents ?"},{"a":"atlab_aang","t":"Ah... Je... n’en ai plus."},{"a":"atlab_aang","t":"Ma famille... tous les Nomades de l’Air ont été tués par la Nation du Feu."},{"a":"atlab_aang","t":"... Je suis le seul survivant."},{"a":"elderowen","t":"Miséricorde ! Toutes mes condoléances, pauvre enfant..."},{"a":"elderowen","t":"Si tu n’as nulle part où aller, pourquoi ne pas t’installer ici avec tes amis ?"},{"a":"elderowen","t":"La cité vous accueillera sans doute à bras ouverts. Vous êtes déjà très populaires !"},{"a":"atlab_aang","t":"Merci pour cette généreuse proposition... mais je ne peux pas accepter."},{"a":"atlab_aang","t":"En ce moment même, le seigneur du feu Ozai prépare déjà son prochain méfait."},{"a":"atlab_aang","t":"Quand la comète de Sozin illuminera à nouveau le ciel, la Nation du Feu partira à la conquête de mon monde..."},{"a":"atlab_aang","t":"Le Royaume de la Terre... Les Tribus de l’Eau... Ils subiront le même sort que les Nomades de l’Air."},{"a":"atlab_aang","t":"En tant qu’Avatar, je suis le seul à pouvoir l’arrêter... mais je ne suis pas prêt."},{"a":"elderowen","t":"Quel terrible fardeau pour un enfant..."},{"a":"elderowen","t":"Quoi qu’il en soit, sache que tu as le soutien inconditionnel de notre cité."},{"a":"atlab_aang","t":"Merci beaucoup. Vous avez déjà fait énormément pour nous !"},{"a":"atlab_aang","t":"On reviendra tous vous voir quand tout sera terminé !"}]},{"id":"atlab_aang_04","i":4,"title":"Le présage de Sozin","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"mana","t":"Avatar. Nos chemins se croisent enfin."},{"a":"atlab_aang","t":"Qui êtes-vous ? Comment me connaissez-vous ?"},{"a":"mana","t":"La présence de l’Avatar est tel un phare pour le troisième œil."},{"a":"atlab_aang","t":"Oh, de la divination... Sans façon."},{"a":"mana","t":"Toi qui es légion, mais pas encore entier..."},{"a":"mana","t":"Un rude combat t’attend contre le seigneur du feu."},{"a":"atlab_aang","t":"Ozai... Vous le connaissez ?"},{"a":"mana","t":"Sous l’œil de la comète, la terre sera fendue et les champs réduits en cendres !"},{"a":"atlab_aang","t":"Je le sais bien ! Mais que faire ?"},{"a":"mana","t":"Le flux du destin est inexorable."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"... Mais les braves peuvent en tirer les ficelles pour l’infléchir."},{"a":"mana","t":"Un allié inattendu et une alliance fragile seront peut-être la clé."},{"a":"atlab_aang","t":"Merci... J’y réfléchirai."},{"a":"mana","t":"..."},{"a":"mana","t":"Sois courageux, Avatar. Reste fidèle à toi-même et la victoire t’appartiendra."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"L’ombre du roi","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"[...] Et là, j’ai tailladé le troubelin avec mon épée, tchac !"},{"a":"elderowen","t":"Ho, mais quelle histoire, Argon !"},{"a":"elderowen","t":"Ah, l’ardeur de la jeunesse..."},{"a":"elderowen","t":"Je dois bien dire que c’est généreux de ta part d’accompagner un vieillard dans sa promenade matinale."},{"a":"argon","t":"Ce n’est rien ! Si je veux devenir chevalier un jour, je me dois d’aider mon prochain !"},{"a":"elderowen","t":"Comme ton père, hein ? Je suis sûr que tu feras un grand chevalier, mon garçon."},{"a":"elderowen","t":"Hé, tu pourrais même intégrer la garde royale !"},{"a":"elderowen","t":"Oh, mais regarde, le roi est justement là au marché. Pourquoi ne pas lui demander ?"},{"a":"argon","t":"VOTRE MAJESTÉ ! Je viens me mettre à votre service comme chevalier."},{"a":"king","t":"Mais qu’est-ce que ça signifie ?! Sia, occupez-vous donc de ce manant."},{"a":"sia","t":"Bien, sire."},{"a":"sia","t":"Alors, jeune homme, que veux-tu ?"},{"a":"argon","t":"Oh ! Je, euh..."},{"a":"argon","t":"Je m’appelle chevalier, et je voudrais devenir un Argon !"},{"a":"argon","t":"Non, euh, attendez..."},{"a":"sia","t":"En tout cas, tu ne manques pas de culot."},{"a":"sia","t":"Si tu es si déterminé, viens me trouver dans la cour du château la semaine prochaine."},{"a":"sia","t":"Et entraîne-toi, hein ! Il n’y a pas de place pour les feignants dans la garde royale..."}]},{"id":"argon_02","i":2,"title":"Séquence d’entraînement","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Qu’est-ce que tu fais ici, Argon ?"},{"a":"argon","t":"Je m’entraîne comme un fou ! J’ai enfin une occasion de devenir un chevalier du roi."},{"a":"lilu","t":"Du roi ? Ou de Sia, sa mystérieuse conseillère ?"},{"a":"argon","t":"C’est comme ça qu’elle s’appelle ? Han, même son nom est beau..."},{"a":"lilu","t":"..."},{"a":"argon","t":"Rah, mais qu’est-ce que je dis ? Il n’y a que le roi qui compte !"},{"a":"argon","t":"Je dois devenir chevalier, au diable le reste !"},{"a":"lilu","t":"C’est ça... Attends, je vais te soigner."},{"a":"argon","t":"Merci. Aïeuh ! Il pique, ce sort."}]},{"id":"argon_03","i":3,"title":"Deux côtés d'une pièce","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"OK ! Sia va arriver d'un moment à l'autre !"},{"a":"argon","t":"Ma formation a été bénéfique, je suis prêt !"},{"a":"argon","t":"...Mais peut-être encore beaucoup trop nerveux..."},{"a":"argon","t":"Oh, bonjour ! Oui, toi là, dans les buissons, bonjour !"},{"a":"yami","t":"... !"},{"a":"argon","t":"Toi aussi, tu veux devenir chevalier ?"},{"a":"argon","t":"Sia ne va pas tarder ! Pas la peine de te cacher, elle est très gentille."},{"a":"yami","t":"Sia... !"},{"a":"yami","t":"Il faut que j’y aille. Au revoir."},{"a":"argon","t":"U... Une minute !"},{"a":"argon","t":"Ouah ! Une bombe fumigène ?!"},{"a":"argon","t":"Vraiment étrange, cette fille..."},{"a":"sia","t":"Jeune homme, à qui parlais-tu ?"},{"a":"argon","t":"Ah, Sia ! Juste à une passante un peu timide ! Il ne faut pas y prêter attention !"},{"a":"sia","t":"... Je vois. Eh bien, tu sembles toujours être aussi déterminé."},{"a":"sia","t":"Es-tu prêt à risquer ta vie pour devenir l'un des chevaliers du Roi ?"},{"a":"argon","t":"Vas-y, c'est clair ! Euh... je veux dire, oui bien sûr ! Je veux que mon père soit fier de moi !"},{"a":"sia","t":"Bien. Pour ta première mission, j'ai un événement important qui t'attend..."}]},{"id":"argon_04","i":4,"title":"Main vide","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Dis-mois que tu plaisantes !"},{"a":"sia","t":"Tu as coincé l'assassin... mais tu ne l'as pas arrêtée."},{"a":"sia","t":"Non seulement cela, mais tu oses dire que tu l'as LAISSÉE PARTIR parce que tu crois que c'est quelqu'un de bien ?!"},{"a":"argon","t":"..."},{"a":"sia","t":"Qu'est-ce que c'est que ces foutaises ?"},{"a":"sia","t":"Tu réalises BIEN que cette fille, cet assassin, a tenté de tuer notre Roi, l'homme que tu as fait serment de protéger ?"},{"a":"sia","t":"Un tel incident a des conséquences bien plus dangereuses que ton intellect limité n'est en capacité de comprendre."},{"a":"sia","t":"Pff... J'imagine que le Roi a le dernier mot quand il s'agit de révoquer ses chevaliers..."},{"a":"sia","t":"... Mais ne t'attends pas à ce que je parle de toi en termes flatteurs. Tu peux disposer."},{"a":"argon","t":"..."},{"a":"argon","t":"Oh là là..."},{"a":"argon","t":"Désolé, papa."}]},{"id":"argon_a","i":4,"title":"La tour des Titans","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"elderowen","t":"La tour des Titans, c’est ça ?"},{"a":"lilu","t":"Mais qu’est-ce que c’est, cette tour, au juste ?"},{"a":"argon","t":"On entend des guerriers en parler, mais personne ne l’a jamais vue en vrai."},{"a":"elderowen","t":"Oui, cette tour est un endroit de légende. Personne ne sait vraiment si elle existe."},{"a":"elderowen","t":"D’aucuns disent qu’elle apparaît comme par magie pour mettre les plus grands héros au défi de gravir ses étages..."},{"a":"elderowen","t":"Puis qu’elle disparaît aussi soudainement en effaçant les souvenirs de tous ceux qui l’ont vue."},{"a":"argon","t":"En effaçant les souvenirs ?!"},{"a":"lilu","t":"C’est bizarre, ça... Mais d’où viendrait la légende, alors ?"},{"a":"argon","t":"Ben oui ! Pour ça, il faut bien qu’il y ait des gens qui s’en souviennent."},{"a":"elderowen","t":"On dit aussi que la tour reconnaît la valeur de ceux qui viennent à bout de son défi."},{"a":"elderowen","t":"Et qu’à leur retour, eux conservent leurs souvenirs et tout ce que leur a apporté l’expérience."},{"a":"elderowen","t":"Plus précisément, qu’une part de chacun reste dans la tour, et qu’une part de la tour repart avec eux."},{"a":"elderowen","t":"Bon, voilà pour l’histoire du jour. Merci de prendre le temps d’écouter un pauvre vieillard."},{"a":"lilu","t":"Quelle histoire ! Je me demande si elle existe vraiment."},{"a":"argon","t":"Mais oui, j’aimerais tellement explorer ce genre de donjon !"},{"a":"lilu","t":"Il y a une chose étrange, quand même... Comment est-ce qu’Owen sait tout ça ?"},{"a":"argon","t":"!!"}]},{"id":"argon_05","i":5,"title":"Chevalier errant","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"<Soupir>"},{"a":"steel","t":"Oh, mais si c’est pas Argon ! Comment ça va, aujourd’hui ?"},{"a":"argon","t":"Oh, salut, Brohm. Il y aurait du travail pour moi ?"},{"a":"steel","t":"Rien aujourd’hui, mon bon sire Argon. Qu’est-ce qui ne va pas ?"},{"a":"argon","t":"C’est juste Argon, maintenant. J’ai... J’ai perdu mon titre."},{"a":"steel","t":"Oh, ça, ça doit faire mal."},{"a":"steel","t":"Mais... « Quoi qu’il arrive, il faut rester positif ! Tu vas t’en sortir ! »"},{"a":"steel","t":"Je suis sûr que la chance va pas tarder à tourner !"},{"a":"argon","t":"Si, c’est vrai... Merci, Brohm."},{"a":"argon","t":"Je, euh... En attendant, je serai sur la grand place."},{"a":"argon","t":"<Soupir>"}]},{"id":"argon_b","i":5,"title":"Moi, un titan ?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"lilu","t":"Bonjour... Argon..."},{"a":"argon","t":"<Bâille> (...) Salut."},{"a":"lilu","t":"À toi aussi ça te le fait, hein ?"},{"a":"argon","t":"Oui ! Je suis crevé ! J’ai l’impression d’avoir passé la nuit à me battre."},{"a":"lilu","t":"Et regarde, ton bouclier est plein de marques !"},{"a":"argon","t":"Hein ? Mais c’est vrai ! J’aurais pu jurer qu’il était brillant comme un sou neuf, hier..."},{"a":"lilu","t":"Mais dis... tu ne penses quand même pas... ?"},{"a":"polonia","t":"Holà, moussaillons ! Est-ce que par hasard quelqu’un serait intéressé par un petit lot de <c1>grèves du mastodonte</c1> ?"},{"a":"lilu","t":"Ben non... et encore moins vingt d’un coup ! Où est-ce que vous avez trouvé tout ça ?"},{"a":"polonia","t":"Ha ! Ça, c’est une bonne question. Je n’en ai pas une traître idée."},{"a":"polonia","t":"Je me demande si je ne fais pas de la piraterie somnambule. Ça doit être mon âme de grand corsaire qui se réveille."},{"a":"lilu","t":"Alors la pirate rigolote a ça aussi..."},{"a":"lilu","t":"Est-ce qu’on aurait tous affronté la tour et elle aurait effacé nos souvenirs ?"},{"a":"argon","t":"Ça voudrait dire qu’on n’était pas assez forts pour aller jusqu’au bout..."},{"a":"argon","t":"Alors je vais m’entraîner d’arrache-pied pour la prochaine fois, vous allez voir !"}]},{"id":"argon_06","i":6,"title":"Mise en lumière","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Ainsi, ce soi-disant chevalier avait l’assassin à sa merci..."},{"a":"sia","t":"Mais a décidé de la relâcher parce qu’il pensait qu’elle était quelqu’un de bien."},{"a":"king","t":"Quelle histoire fascinante ! Ce nouveau chevalier semble être un jeune homme plein de promesse !"},{"a":"sia","t":"Avec tout le respect qui vous est dû, sire..."},{"a":"sia","t":"Cet homme a échoué à arrêter votre assassin sur un simple coup de tête."},{"a":"king","t":"Un acte digne d’un <c1>paladin</c1>, ne pensez-vous pas ?"},{"a":"sia","t":"Pardon... ?"},{"a":"king","t":"Tenir son ennemi juré à sa merci, mais être capable de voir au-delà de la haine et du conflit..."},{"a":"king","t":"Et le laisser partir, prêt à jouer jusqu’à son rang sur la certitude de sa rédemption."},{"a":"king","t":"C’est un remarquable acte de bravoure et de bienveillance !"},{"a":"sia","t":"Je... Je dois admettre que je n’avais pas vu les choses sous cet angle, sire."},{"a":"sia","t":"Mais le royaume n’a plus vu de véritable aspirant paladin depuis des décennies..."},{"a":"sia","t":"Faut-il convoquer le conseil des chevaliers pour discuter de la question ?"},{"a":"king","t":"Absolument pas ! Je vais me charger des formalités moi-même."},{"a":"sia","t":"Comme vous le souhaitez, sire. Je demande une escorte sur-le-champ."},{"a":"king","t":"Nul besoin de ça. Je serai aussi discret qu’une souris !"}]},{"id":"argon_07","i":7,"title":"Le roi incognito","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"king","t":"Faites place, manants ! Un ouvrier tout ce qu’il y a de plus ordinaire passe parmi vous !"},{"a":"tavern","t":"Ah, sire Reinhold ! Ça faisait longtemps. Je vous ouvre un flacon d’ambroisie ?"},{"a":"king","t":"Chuuut ! Aujourd’hui, je suis incognito. Faites comme si je n’étais pas là !"},{"a":"tavern","t":"Mais bien sûr ! Suis-je bête..."},{"a":"king","t":"Vous, là ! Oui, vous, qui vous cachez derrière le comptoir !"},{"a":"argon","t":"Ah ! Euh, désolé votre Majesté, je vais faire de la place..."},{"a":"king","t":"Ne dites pas de bêtises ! Un paladin en devenir est largement digne de s’asseoir à côté de mon auguste personne."},{"a":"argon","t":"S’asseoir à côté de... Hein, vous avez dit paladin ?!"},{"a":"king","t":"Absolument ! Dans mon infinie sagesse, je perçois un grand potentiel en vous !"},{"a":"king","t":"Malgré vos méthodes, euh, peu orthodoxes, vous avez le cœur pur et un sens de la justice tout bonnement admirable."},{"a":"king","t":"Ainsi, le royaume vous déclare digne de passer l’épreuve des paladins !"},{"a":"argon","t":"L’épreuve des paladins... Ouah !"},{"a":"argon","t":"Je connais ces épreuves ! Chacune est unique et choisie par l’aspirant paladin en personne..."},{"a":"argon","t":"Il faut que ce soit une mission dangereuse, comme occire un dragon ou détruire une relique maléfique."},{"a":"king","t":"C’est bien ça ! N’importe quel exploit pour le bien royaume fera l’affaire s’il est assez courageux et désintéressé."},{"a":"argon","t":"C’est compris. Merci, votre Majesté, vous ne le regretterez pas !"},{"a":"king","t":"Bien sûr que non. Je ne me trompe jamais !"},{"a":"king","t":"Bon, et maintenant, quitte à être là incognito..."},{"a":"king","t":"Vous, là ! Mon bon vieillard, apprenez-moi donc à jouer aux cartes."},{"a":"master","t":"Aux cartes, hein ? Mais vous savez, le vieux Théodore ne joue que pour des grosses mises..."}]},{"id":"argon_08","i":8,"title":"Retrouver la flamme","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Argon ! Où tu cours comme ça ?"},{"a":"argon","t":"Oh, Lilu ! Je vais devenir paladin !"},{"a":"lilu","t":"Hein ? Mais c’est génial ! Comment est-que... ?"},{"a":"argon","t":"Le roi m’a dit de surmonter une épreuve, c’est le seul moyen de se montrer digne du titre de paladin."},{"a":"lilu","t":"Une épreuve... Et tu sais ce que tu vas faire ?"},{"a":"argon","t":"..."},{"a":"argon","t":"Je n’en ai malheureusement pas la moindre idée."},{"a":"argon","t":"Il faut que ce soit épique et carrément glorieux..."},{"a":"lilu","t":"Mais glorieux, tu l’es déjà ! Tu as vaincu des monstres aux quatre coins du monde."},{"a":"argon","t":"C’est vrai, mais il faut quelque chose en plus."},{"a":"argon","t":"Il paraît qu’on trouve des monstres à plumes au pic de Morneflèche, peut-être que ça ferait l’affaire..."},{"a":"lilu","t":"Quoi que ce soit, je suis sûre que tu seras à la hauteur !"},{"a":"argon","t":"Merci. Même quand j’ai perdu mon titre de chevalier, tu as gardé foi en moi."},{"a":"lilu","t":"Oh, ce n’était rien."},{"a":"lilu","t":"Enfin, euh, tu vas avoir besoin d’aide pour cette grande quête. Je vais te préparer quelques parchemins de soins !"},{"a":"argon","t":"Génial ! En avant !"}]},{"id":"argon_09","i":9,"title":"Choc de Morneflèche (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Eurh... Mais quel endroit pénible !"},{"a":"argon","t":"Des heures à grimper et pas la moindre harpie en vue... et j’ai même été attaqué par des assassins !"},{"a":"argon","t":"Tiens, ils avaient un peu la même dégaine que la petite ninja, non ?"},{"a":"argon","t":"Pfiouh, heureusement que Lilu m’avait donné des parchemins de soins."},{"a":"argon","t":"Allez, je fais une petite pause."},{"a":"argon","t":"Euh... ?"},{"a":"yami","t":"Encore toi."},{"a":"argon","t":"C’est l’assassin du roi !"},{"a":"argon","t":"C’est un signe du destin... une proie encore plus glorieuse qu’une harpie !"},{"a":"yami","t":"Essaie un peu. Si tu bouges, je t’exécute."}]},{"id":"argon_10a","i":10,"title":"Retour triomphant","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Sire Reinhold ! Ma quête est terminée !"},{"a":"king","t":"Sublimissime ! Quelle épouvantable créature avez-vous donc terrassée ?"},{"a":"argon","t":"Ah. À ce sujet, euh..."},{"a":"yami","t":"Salut."},{"a":"king","t":"Mais qu’est-ce que ça signifie ?!"},{"a":"sia","t":"Gardes, saisissez-les ! Tous les deux !"},{"a":"argon","t":"Non, attendez ! Elle veut faire amende honorable !"},{"a":"king","t":"Ah... ah oui ?"},{"a":"yami","t":"Je viens... Je viens présenter mes excuses."},{"a":"sia","t":"Sire, vous n’allez quand même pas croire..."},{"a":"argon","t":"Je réponds d’elle, sur mon honneur de chevalier !"},{"a":"king","t":"Très bien. Je consens à écouter son plaidoyer."},{"a":"sia","t":"Pff. Je craignais que ça tourne comme ça."},{"a":"sia","t":"Gardes ! Faites venir des renforts, et restez à l’affût du moindre geste !"},{"a":"sia","t":"Argon, je vous prie d’attendre dehors pendant que nous interrogeons... l’intruse."},{"a":"argon","t":"À vos ordres !"},{"a":"argon","t":"(Est-ce que j’aurais fait une énorme boulette ?)"}]},{"id":"argon_10b","i":11,"title":"Rédemption","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Quel casse-tête... Je n’avais pas besoin de ça aujourd’hui."},{"a":"argon","t":"Dame Sia ! Alors ?"},{"a":"sia","t":"Contre toute attente, le sire Reinhold est disposé à absoudre celle qui a tenté de l’assassiner."},{"a":"sia","t":"Je ne partage pas la confiance du roi, mais elle a tout de même fourni de précieux renseignements sur l’Ordre azuman."},{"a":"argon","t":"Alors ça veut dire que..."},{"a":"sia","t":"Oui. Nous allons accepter sa reddition et son amende honorable."},{"a":"sia","t":"Elle souffrait d’inanition et nous l’avons confiée aux médecins royaux. Elle devrait s’en remettre."},{"a":"sia","t":"Quant à vous, Argon le paladin..."},{"a":"argon","t":"Le paladin ?!"},{"a":"sia","t":"Oui. Vaincre une proie dangereuse, c’est une chose, mais obtenir la rédemption d’un ennemi juré du royaume..."},{"a":"sia","t":"Il semble qu’après tout, sire Reinhold ne s’était pas trompé à votre sujet."},{"a":"sia","t":"Allez fêtez l’occasion, cher paladin. Je ne doute pas que vous serez bientôt très occupé !"},{"a":"argon","t":"Je vais faire ça ! Merci !"},{"a":"argon","t":"Papa... J’espère que tu es fier de moi."}]},{"id":"argon_epilogue","i":12,"title":"Épilogue","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Un paladin ?! Argon, tu as réussi !"},{"a":"argon","t":"Pendant un moment, j’ai vraiment cru que j’avais tout raté."},{"a":"argon","t":"Mais mon père avait raison. L’important, c’était d’écouter mon cœur !"},{"a":"lilu","t":"Oh, mais ça veut dire que tu vas être envoyé en campagne par-delà les mers ?"},{"a":"argon","t":"Pas pour l’instant. Sia dit que je peux former les héros qui veulent devenir paladins."},{"a":"lilu","t":"Ah, quel soulagement ! Mais... je ne te vois pas vraiment en professeur."},{"a":"lilu","t":"Tu ne seras pas occupé avec plein de quêtes de paladin super importantes ?"},{"a":"argon","t":"Je ferai de mon mieux ! Le royaume compte sur moi !"},{"a":"tavern","t":"Salut, noble paladin !"},{"a":"tavern","t":"Brohm m’a dit qu’il lui fallait encore des gants pour la fonderie."},{"a":"argon","t":"Oui ! Tout de suite !"},{"a":"lilu","t":"Eh... Certaines choses ne changeront jamais."},{"a":"tavern","t":"En tout cas, pas notre Argon."}]},{"id":"argon_c","i":13,"title":"Gravé dans la pierre","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"La potion... n'a pas marché, c'est ça ?"},{"a":"lilu","t":"Hah... On avait tellement travaillé dessus..."},{"a":"lilu","t":"Désolée, Argon. Je n'ai pas assuré... J'espère que ça n'est pas trop inconfortable là-dedans."},{"a":"elderowen","t":"Hum... quelles terribles nouvelles !"},{"a":"lilu","t":"Il nous reste encore des options, mais..."},{"a":"lilu","t":"C'est vraiment dur quand il n'est pas avec nous."},{"a":"elderowen","t":"La cité semble vraiment vide sans lui, pas vrai ?"},{"a":"lilu","t":"Comme une fête d'anniversaire sans amis."},{"a":"lilu","t":"Se lamenter ne le ramènera pas plus vite. Je m'y remets."},{"a":"lilu","t":"Nous pourrions peut-être demander à Donovan de nous aider."},{"a":"lilu","t":"Ça va être cher, mais nous pouvons mettre notre argent en commun !"},{"a":"lilu","t":"Je sais que tu ne vas nulle part, mais... reste là ! On va te sauver !"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"Un samouraï insolite","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Un vrai samouraï... J’ai hâte !"},{"a":"argon","t":"Dame samouraï ! Je suis Argon, un apprent..."},{"a":"ashley","t":"Yo. Moi, c’est Ashley. Ça roule ?"},{"a":"argon","t":"« Yo » ?"},{"a":"tavern","t":"On ne met pas les pieds sur la table, je vous prie !"},{"a":"ashley","t":"Tss. D’accord."},{"a":"ashley","t":"Et donc ? C’était pour quoi ?"},{"a":"argon","t":"Hum... Les samouraïs ne sont pas un peu plus, euh... formels ? En général ?"},{"a":"ashley","t":"Hu ? Ah, au pays ils étaient assez coincés avec ça, oui."},{"a":"ashley","t":"Mais je suis libre de tout ça. Je ne suis plus qu’un ronin, un samouraï sans seigneur."},{"a":"argon","t":"Ah... Je vois !"},{"a":"argon","t":"J’avais une quête prévue avec Lilu au château Hanté, mais..."},{"a":"argon","t":"Je suis retenu à la salle d’entraînement. Tu pourrais me remplacer ?"},{"a":"ashley","t":"Pas de problème. Mais tu m’en dois une, petit chevalier."}]},{"id":"ashley_02","i":2,"title":"Armée jusqu’aux dents","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"ashley","t":"Lilu, c’est ça ?"},{"a":"lilu","t":"Oui ! Enchantée !"},{"a":"ashley","t":"Super. En route, alors."},{"a":"lilu","t":"Euuh, attends !"},{"a":"lilu","t":"Les préparatifs ne sont pas terminés ! Les potions, à manger, ..."},{"a":"ashley","t":"On s’en fout, on n’a pas besoin de tout ça."},{"a":"ashley","t":"Soit on survit, soit on meurt. Pas de demi-mesure."},{"a":"lilu","t":"Mais... non ! C’est beaucoup trop risqué !"},{"a":"ashley","t":"Moi, j’y vais. C’est par là, c’est ça ?"},{"a":"lilu","t":"Non ! Par là, c’est les bois Hurlants..."},{"a":"argon","t":"Euh... Bonne chance ?"}]},{"id":"ashley_03","i":3,"title":"Une vie sur le fil","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"ashley","t":"Alors, les monstres, c’est tout ? VENEZ VOUS BATTRE !"},{"a":"lilu","t":"Ashley ! Ralentis un peu ! Je n’arrive pas à soigner assez vite !"},{"a":"ashley","t":"Tout ça... n’est... RIEN !!"},{"a":"ashley","t":"Pfiouh. Joli petite bagarre, hein ?"},{"a":"lilu","t":"Mais tu plaisantes ?! Tu as failli mourir !"},{"a":"lilu","t":"Pas étonnant que tu y aies laissé un bras si tu es si téméraire !"},{"a":"ashley","t":"Oh. Ça, c’était autre chose."},{"a":"ashley","t":"Cette erreur-là... on ne m’y reprendra pas."},{"a":"lilu","t":"Humpf. Bon, ces soins-là seront sans anesthésie."},{"a":"lilu","t":"C’est de ta faute, après tout. Alors serre les dents."},{"a":"ashley","t":"Ha ha... ha... T’inquiète, j’encaisse."},{"a":"ashley","t":"Aïeuh ! Aïe aïe aïe..."}]},{"id":"ashley_a","i":4,"title":"Déjà-vu","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"ashley","t":"Yo. Qu’est-ce que c’est que tous ces monstres minuscules ?"},{"a":"elven","t":"Tu dois parler de mes chers familiers. Bienvenue."},{"a":"elven","t":"Les champions qui s’en montrent dignes peuvent adopter un fidèle petit compagnon."},{"a":"ashley","t":"Ah ouais, des compagnons ? Je vois."},{"a":"ashley","t":"Bon. Toi, le petit tout vert. Je vais t’appeler <c1>Chafouin</c1>. Viens avec moi."},{"a":"ashley","t":"Une petite <c1>Boule de neige</c1> toute mignonne. Je vais te porter."},{"a":"elven","t":"Ah, j’ai bien peur que..."},{"a":"ashley","t":"Ouah, mais qu’il est laid, ce volatile !"},{"a":"ashley","t":"Ce sera <c1>Hirondelle</c1>, alors. Je t’emmène aussi."},{"a":"elven","t":"Je vois... Amusez-vous bien, mes petits."}]},{"id":"ashley_04","i":5,"title":"Quête échouée avec succès","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Comment s'est passée la quête hier ? Lilu semblait très contrariée..."},{"a":"ashley","t":"Je suis revenue en un seul morceau. Malheureusement."},{"a":"argon","t":"Euh ? Ce n'est pas une bonne nouvelle ?"},{"a":"king","t":"Salutations, manants ! Admirez ma splendeur à votre aise !"},{"a":"ashley","t":"Ah, votre royale majesté ! Ashley au rapport !"},{"a":"king","t":"Quel beau spécimen de soldat ! Continuez comme ça !"},{"a":"ashley","t":"Oui sire ! Merci, sire !"},{"a":"tavern","t":"Désolée Reinhold, votre cru n'est pas encore arrivé."},{"a":"king","t":"Très bien ! Je reviendrai demain matin !"},{"a":"argon","t":"Qu'est-ce que c'était que ça ?"},{"a":"ashley","t":"Oh, euh. Je servais un noble. Les vieilles habitudes ont la vie dure."},{"a":"argon","t":"Super ! Dis-moi tout !"},{"a":"ashley","t":"Non."}]},{"id":"ashley_05","i":6,"title":"Le Récit Tournant","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"ashley","t":"... Et puis j'ai dit au type..."},{"a":"ashley","t":"« Armé et paré ? Et bien, la deuxième partie est vraie ! »"},{"a":"argon","t":"Hahaha !"},{"a":"argon","t":"... Mais Ashley, à propos de ce seigneur dont tu as parlé avant..."},{"a":"ashley","t":"Aaaah... Tu ne lâcheras pas l'affaire. Bon."},{"a":"ashley","t":"... Les samouraïs ont un seigneur, un Daimyo. Nous le servons et le protégeons au prix de notre vie."},{"a":"argon","t":"C'est très honorable !"},{"a":"ashley","t":"Par une belle journée, il déjeunait, comme d'habitude..."},{"a":"ashley","t":"Et soudain, boum. Des ninjas. Partout dans la pièce. Qui voulaient tous la tête de mon maître."},{"a":"ashley","t":"La lutte a été acharnée. Ce n'était pas la première fois. Mais..."},{"a":"ashley","t":"J'ai été blessée. J'ai perdu un bras."},{"a":"ashley","t":"Et je... j'ai fui. Je l'ai laissé mourir."},{"a":"argon","t":"Ashley..."},{"a":"ashley","t":"... RAAAH !!! J'aurais dû mourir là-bas !"},{"a":"ashley","t":"... Naya, ressers-moi ça."},{"a":"tavern","t":"Tu as assez bu pour aujourd'hui, Ashley."},{"a":"ashley","t":"Bon. D'accord. J'ai mon compte."},{"a":"ashley","t":"Très bien. Argon, va dire à Lilu qu'Ashley est sur le point d'entreprendre une quête extrêmement dangereuse."},{"a":"argon","t":"Hein ? Maintenant ?"},{"a":"ashley","t":"Bien sûr. Je vais... disons à la grotte Boréale. Dépêche-toi !"}]},{"id":"ashley_06","i":7,"title":"Œil pour un Je","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"ashley","t":"... Petite ninja. Tu écoutais aux portes ?"},{"a":"yami","t":"... Un peu. On règle ça dehors ?"},{"a":"ashley","t":"Hah ! Je ne suis pas d'humeur à me battre."},{"a":"yami","t":"C'est mon clan qui a fait ça au seigneur Kusunoki. Je suis hors-caste, mais peut-être que mes excuses..."},{"a":"ashley","t":"Merci, mais c'est inutile. Je ne te déteste pas. C'est moi que je hais."},{"a":"yami","t":"Je comprends... Peut-être plus que tu ne peux l'imaginer."},{"a":"yami","t":"Mais même avec ton honneur en lambeaux, ta vie est loin d'être finie."},{"a":"yami","t":"Tu as des amis ici. Cette cité est ta famille. Tu as des compagnons que tu adores."},{"a":"yami","t":"... Et si ça ne suffit pas, je peux t'offrir un duel à mort honorable."},{"a":"ashley","t":"Un assassinat de ninja gratuit ? Tu me gâtes."},{"a":"ashley","t":"Merci, mais non. Par contre, je le garde en mémoire."},{"a":"yami","t":"Comme tu veux."}]},{"id":"ashley_07","i":8,"title":"Un ultime combat","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Ouf... Pouf... Ashley n'est pas là..."},{"a":"lilu","t":"Elle s'est encore perdue ?"},{"a":"lilu","t":"Non, attends. On m'a joué un tour ?"},{"a":"ashley","t":"Je croyais que je me dirigeais vers le Volcan du Lac cendré..."},{"a":"ashley","t":"Tant pis, ça fera l’affaire."},{"a":"ashley","t":"Aaaallez ! Debout, bande de crétins ! Ashley est là !"},{"a":"monster_Grotto_Mob","t":"L'humain est... saoul ?"},{"a":"ashley","t":"Pas de soigneur importun aujourd'hui, juste moi et mon désir de mort ! Je n'arrêterai pas avant de décéder !"},{"a":"ashley","t":"Quoi qu'il arrive, je suis gagnante ! Alors qui sera le premier ?"},{"a":"monster_Ruins_Mob","t":"Grah ! Allez, venez !"},{"a":"ashley","t":"À la bonne heure !"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"priest","t":"Par la déesse... est-ce le bon endroit ?"},{"a":"priest","t":"Mince, quel massacre."},{"a":"monster_Grotto_Mob","t":"Hi hi hi."},{"a":"priest","t":"Pardon les monstres. Merci de me laisser récupérer mon compagnon."},{"a":"monster_Grotto_Mob","t":"Absolument pas ! NON ! Elle s'est fichue de nous ! Cette samuraï est morte de chez mort !"},{"a":"priest","t":"Elle vit encore. Notre Ashley est plus coriace que ça."},{"a":"monster_Ruins_Mob","t":"Hein ? Alors il vaudrait mieux que je finisse le travail !"},{"a":"priest","t":"Tu n'en feras rien."},{"a":"monster_Grotto_Mob","t":"Hé hé, hah ! Et tu vas faire quoi ? Nous soigner ?"},{"a":"priest","t":"Tu ne me laisses pas le choix. Que la déesse Asthea te pardonne..."},{"a":"priest","t":"Parce que moi, non."}]},{"id":"ashley_09","i":10,"title":"Alitement Forcé","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"ashley","t":"...Argh..."},{"a":"priest","t":"Tu as enfin repris connaissance."},{"a":"ashley","t":"Hein ? Mince... pas toi aussi. Comment tu m'as trouvée ?"},{"a":"priest","t":"La déesse semble se soucier de toi. Je la représente."},{"a":"ashley","t":"Mince... Allez, doc, laisse-moi mourir."},{"a":"priest","t":"Si c'est vraiment ce que tu veux."},{"a":"ashley","t":"Pfff... Enfin..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"... Mais alors pourquoi tu continues à me SOIGNER ?"},{"a":"priest","t":"Malgré tes paroles, il semble que tu souhaites vivre."},{"a":"priest","t":"La magie de soins ne fait qu'accélérer ta force vitale. Si tu voulais vraiment mourir, je ne pourrais rien faire pour te sauver."},{"a":"ashley","t":"Vraiment..."},{"a":"priest","t":"Repose-toi pour l'instant. Tu as de quoi réfléchir."}]},{"id":"ashley_10","i":11,"title":"Le temps de réfléchir","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Te revoilà ! Lilu te cherchait partout !"},{"a":"argon","t":"...Tu as l'air un peu mal en point, toi aussi."},{"a":"ashley","t":"Ne t'en fais pas, j'ai été rafistolé. J'ai aussi eu droit à un savon."},{"a":"argon","t":"De Freyja ? C'est difficile à imaginer."},{"a":"ashley","t":"Ouais. Elle m'a dit de commencer à réfléchir. Alors je réfléchis."},{"a":"tavern","t":"Réfléchir ? Ça, c'est nouveau !"},{"a":"ashley","t":"Arrête !"},{"a":"ashley","t":"...c'est ce que j'aimerais dire, mais tu as raison."},{"a":"ashley","t":"J'ai été si longtemps bloqué dans le passé que j'en ai oublié de penser."},{"a":"argon","t":"Penser à quoi ?"},{"a":"ashley","t":"Hmm. Plein de choses."},{"a":"ashley","t":"Sans que je m'en aperçoive, il semble que j'aie accumulé beaucoup de choses auxquelles je tenais."},{"a":"ashley","t":"La cité. Le peuple. Le marchand. Toi aussi, jeune chevalier."},{"a":"ashley","t":"Il n'a fallu que plusieurs frôlements de la mort pour s'en rendre compte. On dirait que je suis un peu lent à la détente, hum."},{"a":"argon","t":"Je suis honoré, mademoiselle Samouraï !"},{"a":"ashley","t":"Toujours un Ronin ici. Ne t'attends pas à ce que ça change de sitôt."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Épilogue","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"ashley","t":"Salut, Lilu. Je pars faire une autre quête. Tu veux venir ?"},{"a":"lilu","t":"Pfff ! Pour que tu m'envoies encore au mauvais endroit ?"},{"a":"lilu","t":"Ou pour que tu attaques imprudemment les monstres au point que je doive te recoudre à nouveau ?"},{"a":"ashley","t":"...Non, je suis une nouvelle femme. Je vais me modérer, une main derrière le dos."},{"a":"lilu","t":"Hum... si tu le dis."},{"a":"lilu","t":"Une minute..."},{"a":"ashley","t":"Ha ha ! Je plaisante."},{"a":"ashley","t":"Si tu protèges mes arrières, je protègerai tes arrières."},{"a":"lilu","t":"Ça me va ! Mais cette fois, promets-le-moi."},{"a":"lilu","t":"Si la situation dégénère... on bat en retraite. TU bats en retraite."},{"a":"ashley","t":"Promis. Sur mon honneur de ronin, pour ce que ça vaut."},{"a":"ashley","t":"Après tout, notre foyer nous attend."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"Papa est rentré","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"bjorn","t":"Coucou les enfants ! Papa est rentré !"},{"a":"steel","t":"Papa !"},{"a":"wood","t":"... Papa."},{"a":"bjorn","t":"Pourquoi cette grise mine, Gorza ?"},{"a":"wood","t":"Ça fait des mois que tu es parti !"},{"a":"bjorn","t":"C’est ça, la vie de forestier ! La nature sauvage, loin de chez soi."},{"a":"wood","t":"Pfft. Ça ne te ferait pas de mal de passer plus souvent."},{"a":"bjorn","t":"J’aimerais bien, mais j’ai fort à faire avec le volcan du Lac cendré !"},{"a":"wood","t":"Le volcan ? Je croyais que tu t’occupais du pic de Morneflèche..."},{"a":"bjorn","t":"... Ah bon ?"},{"a":"bjorn","t":"J’ai dû me mélanger les pinceaux ! Har har !"},{"a":"bjorn","t":"Enfin bref, je vous ai rapporté des souvenirs ! Venez voir !"},{"a":"steel","t":"Oh ! J’espère qu’il y a un broyeur en peluche !"}]},{"id":"bjorn_a","i":1,"title":"Bamham le bon pote","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"bjorn","t":"Les enfants, vous voulez bien surveiller Bamham cinq minutes ?"},{"a":"wood","t":"Ce méchant sanglier ? Pas question. Tu te le gardes."},{"a":"steel","t":"Pardon, papa, mais il est un peu... taré, non ?"},{"a":"bjorn","t":"Oh, allons donc ! Il est mignon comme un cœur !"},{"a":"wood","t":"Papa, il devient fou furieux dès que tu le poses."},{"a":"bjorn","t":"Cette fois-là, c’était un accident. Il s’est excité un peu trop, c’est tout."},{"a":"wood","t":"Et toutes les autres fois ?"},{"a":"bjorn","t":"C’étaient... aussi des accidents. Bébé Bamham ne ferait pas de mal à une mouche !"},{"a":"wood","t":"Oh que si, et plutôt deux fois qu’une."},{"a":"wood","t":"Écoute, papa, il vaudrait mieux que tu le gardes avec toi quand tu es en ville."},{"a":"steel","t":"... Pour notre sécurité à tous."},{"a":"bjorn","t":"Bon, d’accord, j’ai compris. C’est pas grave, Bamham, moi je t’aime."},{"a":"bjorn","t":"Holà holà holà ! Doucement, Bamham !"}]},{"id":"bjorn_02","i":2,"title":"Les courses de Bjorn","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"bjorn","t":"Merci pour cet accueil chaleureux, tout le monde ! Ça fait du bien de rentrer !"},{"a":"elderowen","t":"C’est un vrai soulagement de te retrouver sain et sauf. Après tous ces mois, on craignait le pire..."},{"a":"bjorn","t":"Pardon, pardon ! C’est comme ça, la vie de forestier ! Har har !"},{"a":"oils","t":"Te connaissant, je parie que tu penses déjà à ta prochaine expédition !"},{"a":"bjorn","t":"Har har ! Percé à jour ! On part demain à l’aube, en fait !"},{"a":"oils","t":"Ne change jamais, Bjorn. Je surveillerai Brohm et Gorza en ton absence."},{"a":"oils","t":"... Si c’est sur ton chemin, pourrais-tu me récolter quelques lumignons ?"},{"a":"bjorn","t":"Bien sûr, sans problème !"},{"a":"elderowen","t":"Oh... mon dos m’élance ces derniers temps. Des perles glacées, ce serait possible ?"},{"a":"bjorn","t":"C’est un petit détour de rien du tout. J’essaierai d’en trouver, l’ancien."},{"a":"engineer","t":"Oh ! Bjorn ! J’aimerais des écailles de wyrmerouille pour ma prochaine expérience, si c’est faisable."},{"a":"bjorn","t":"Bien sûr, bien sûr. C’est noté !"},{"a":"bjorn","t":"Ouf ! Je crois qu’on va devoir prévoir des sacs en plus, Bamham !"}]},{"id":"bjorn_03","i":3,"title":"Tout ce qui pollue est d’or","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"bjorn","t":"Hmm... Tu sens ce que je sens, Bamham ?"},{"a":"bjorn","t":"Eh oui : du métal. Abandonné négligemment, sans doute. Viens, Bam, on va le trouver !"},{"a":"bjorn","t":"Bon petit, montre voir..."},{"a":"bjorn","t":"Hmm. Étrange appareil. Je doute qu’on l’ait laissé là par accident..."},{"a":"bjorn","t":"Je te parie que si je tire un peu sur cette manivelle..."},{"a":"bjorn","t":"Hmm... Oui, c’est bien ce que je pensais."},{"a":"bjorn","t":"... Ça se casse. On n’a pas appris tant que ça, hein ? Har har !"},{"a":"bjorn","t":"Mais je crois qu’on tient notre piste. Ça fait des mois qu’on cherche et ce truc n’était pas là la dernière fois."},{"a":"bjorn","t":"Mieux vaut rentrer demander à un pro. Tu sais que la technologie et moi, ça fait deux !"}]},{"id":"bjorn_04","i":4,"title":"Balise inconnue","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"engineer","t":"Quel étrange ouvrage ! Je n’ai jamais rien vu de tel."},{"a":"engineer","t":"Il semble associer magie et science pour faire office de... balise ? Radar ?"},{"a":"engineer","t":"Vous dites qu’il était dans cet état quand vous l’avez trouvé ?"},{"a":"bjorn","t":"Oui. C’est pas de chance, hein ? Har har !"},{"a":"engineer","t":"Dommage. Tout ce que je peux affirmer, c’est qu’il envoie une information quelconque."},{"a":"engineer","t":"Écoutez, laissez-moi une minute et je vous fabrique un appareil pour vous aider à trouver d’autres de ces... « balises magiques »."},{"a":"bjorn","t":"Génial ! Tu es prêt à y retourner, Bamham ?"},{"a":"bjorn","t":"On ignore de quoi il s’agit au juste... mais ça ne me dit rien qui vaille."},{"a":"bjorn","t":"À nous de découvrir qui est derrière tout ça !"},{"a":"engineer","t":"Bonne chance ! Et... prudence avec les technologies mystérieuses !"}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Recette originale","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"herbalist","t":"Bienvenue à la Maison des remèdes de Maribelle. Comment puis-je vous aider ?"},{"a":"donovan","t":"Dame Maribelle, c’est bien ça ? Je tiens à vous féliciter en personne pour votre dernière création."},{"a":"donovan","t":"Moi qui suis l’inventeur de la potion de renouveau, je trouve que votre recette modifiée est un véritable coup de génie !"},{"a":"donovan","t":"Cette petite touche de pic-de-brume en plus, ça change tout !"},{"a":"herbalist","t":"Attendez... Vous voulez dire que vous êtes Donovan. LE Donovan ? Mais non !"},{"a":"herbalist","t":"La recette de la potion de renouveau a été mise au point il y a quelque chose comme sept cents ans..."},{"a":"herbalist","t":"Même pour un elfe, je ne vous en donnerais pas plus de cent cinquante !"},{"a":"donovan","t":"Vous êtes trop aimable, dame Maribelle."},{"a":"donovan","t":"Disons simplement que toutes mes recettes ne sont pas disponibles dans le commerce..."},{"a":"donovan","t":"Mais je suis certain qu’un maître alchimiste comme vous n’aurait aucune difficulté à les apprendre."},{"a":"donovan","t":"Mais donc, montrez-moi votre choix de pic-de-brume si vous voulez bien."}]},{"id":"donovan_02","i":2,"title":"Terre d’abondance","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"donovan","t":"C’est fascinant... Même les simples pommes de la région sont d’une qualité remarquable."},{"a":"donovan","t":"Je me demande d’où vient ce phénomène."},{"a":"lilu","t":"Si quelqu’un peut vous expliquer, ce sera sans doute Genièvre !"},{"a":"lilu","t":"Oh, désolée. Je ne voulais pas interrompre votre conversation avec, euh, cet arbre."},{"a":"donovan","t":"Tiens, une jeune femme au grand chapeau accompagnée de son fidèle hibou."},{"a":"donovan","t":"Vous devez être madame Lilu."},{"a":"lilu","t":"C’est ça ! Et vous, pas la peine de vous présenter, monsieur Donovan."},{"a":"donovan","t":"On m’a beaucoup parlé du véritable petit prodige de la cité. Tout le plaisir est pour moi."},{"a":"donovan","t":"Alors, ma chère, vous disiez ?"},{"a":"lilu","t":"Ah, oui. Genièvre dit souvent que la terre est débordante de vie dans les alentours."},{"a":"lilu","t":"Elle dit que c’est aussi pour ça qu’elle aime tellement jardiner par ici."},{"a":"lilu","t":"Enfin, bref. J’étais en route pour les grottes de l’Aurore. C’était un plaisir de faire votre connaissance !"},{"a":"donovan","t":"Nous nous reverrons peut-être bientôt."},{"a":"donovan","t":"Hum... Cette jeune fille a peut-être mis le doigt sur quelque chose."},{"a":"donovan","t":"Serait-ce la terre de Kern qui est épuisée ? Tout semble bien plus luxuriant en ce royaume."},{"a":"donovan","t":"Je vais rendre une petite visite à cette horticultrice. Si les ingrédients sont effectivement plus puissants ici..."},{"a":"donovan","t":"Il faut que j’en profite."}]},{"id":"donovan_03","i":3,"title":"Sous le masque","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Vous m’avez fait demander, madame Sia ?"},{"a":"sia","t":"Ah, Lilu. Merci d’être venue si vite."},{"a":"sia","t":"Je crois que tu as déjà fait la connaissance de Donovan... ?"},{"a":"lilu","t":"Oui ! C’est une véritable légende de l’alchimie, je suis bien contente d’avoir pu le rencontrer !"},{"a":"sia","t":"Sois très, très prudente avec cet homme-là."},{"a":"lilu","t":"Hein ?! Mais c’est un vrai gentilhomme ! Et puis, il sait tellement de choses..."},{"a":"sia","t":"Les apparences peuvent être trompeuses. Derrière son visage jeune et fringant se cache un esprit retors depuis des millénaires."},{"a":"lilu","t":"Des millénaires ? Mais même pour un elfe, ça n’est pas possible ! Vous pensez que..."},{"a":"sia","t":"Oui, certains disent qu’il aurait peut-être découvert une sorte d’élixir de longue vie."},{"a":"lilu","t":"Ouah ! Ça c’est une recette que je voudrais bien pour mon grimoire !"},{"a":"sia","t":"Il y a bien des rois qui en diraient autant. Je le soupçonne d’avoir l’empereur de Kern sous son emprise."},{"a":"lilu","t":"Pfouh... C’est compliqué, la politique."},{"a":"lilu","t":"Mais en tout cas, merci ! Je vais me méfier !"},{"a":"sia","t":"Je savais que tu comprendrais."},{"a":"sia","t":"Quant à moi, je vais m’assurer qu’il ne tourne pas autour de notre cher roi, qui peut parfois être... influençable."},{"a":"lilu","t":"Ah oui... il vaudrait peut-être mieux."}]},{"id":"donovan_a","i":3,"title":"Dix pièces d’or, c’est donné","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"leather","t":"Dis, monsieur potions, t’aurais une minute ?"},{"a":"donovan","t":"Eurh... encore un mendiant."},{"a":"donovan","t":"Que me vaut donc, euh... l’honneur ?"},{"a":"leather","t":"Moi, c’est Tamas. Je m’occupe du cuir."},{"a":"leather","t":"Il paraît que tu sais préparer un élixir d’immortalité super cool. Je pourrais en avoir une bouteille ?"},{"a":"donovan","t":"Hum... Je n’ai pas la moindre idée d’où vous auriez pu entendre pareille rumeur."},{"a":"donovan","t":"Et même si c’était vrai, soyez sûr que je ne distribuerais pas un tel trésor si facilement."},{"a":"leather","t":"Je t’en donne dix pièces d’or."},{"a":"donovan","t":"Hors de question ! Il y a eu des guerres entières autour de cette recette ! Tous les empereurs du monde se mettraient à genoux pour une simple gorgée !"},{"a":"leather","t":"T’es vraiment dur en affaires. Allez, quinze pièces d’or et c’est mon dernier mot."},{"a":"donovan","t":"Est-ce donc l’odeur du cuir qui vous a ravagé le cerveau, va-nu-pieds ? Je ne me séparerais pas de cette recette pour tout l’or du monde !"},{"a":"donovan","t":"J’ai à faire. Veuillez ne plus jamais m’adresser la parole."},{"a":"leather","t":"Han, j’ai failli réussir à le convaincre."},{"a":"leather","t":"Dommage... Va falloir que je trouve autre chose à donner à mes moutons."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"Une ombre plane","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"hemma","t":"(...) Le troubelin a vite succombé, mais pas avant de toucher nos compagnons d’armes."},{"a":"hemma","t":"Veuillez leur apporter les soins nécessaires."},{"a":"priest","t":"Bien sûr. Je vais m’occuper de leurs blessures tout de suite."},{"a":"lilu","t":"Salut ! Il paraît qu’il y a une nouvelle ensorceleuse en ville ?"},{"a":"lilu","t":"Moi, c’est Lilu. Enchantée de faire votre connaissance !"},{"a":"hemma","t":"On ne vous a pas menti, jeune Lilu. Notre nom est Hemma. "},{"a":"lilu","t":"« Notre »... ?"},{"a":"hemma","t":"Oui. La nécromancie n’est pas sans conséquences pour ses adeptes."},{"a":"hemma","t":"Il y a toujours une part de vous qui reste de l’autre côté du voile... et d’autres choses qui traversent dans l’autre sens."},{"a":"hemma","t":"Nos pouvoirs nous ont... changée. En mieux, évidemment."},{"a":"lilu","t":"De la nécromancie ? Mais ce n’est pas dangereux ?"},{"a":"hemma","t":"Si, terriblement. Mais les simples tours de passe-passe ne nous suffisent plus."},{"a":"hemma","t":"À présent, si vous voulez bien nous excuser, nous avons à faire. Au revoir."},{"a":"lilu","t":"Une nécromancienne... Cette magie-là est ténébreuse, mon bon Pollux. Mais c’est la première fois que j’en vois une en vrai !"},{"a":"lilu","t":"Elle n’avait pas l’air si méchante... hein ?"}]},{"id":"hemma_02","i":2,"title":"À tout prix","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"elderowen","t":"Une nécromancienne... ?"},{"a":"elderowen","t":"Je ne sais pas trop quoi en penser."},{"a":"hemma","t":"Vous avez raison de vous inquiéter. La nécromancie est un art dangereux qui peut vite dévorer les êtres inférieurs."},{"a":"hemma","t":"Mais nous n’avons rien d’inférieure."},{"a":"elderowen","t":"Et pour les aventuriers qui t’accompagnent ? C’est dans leur force vitale que tu puises pour alimenter tes sorts, n’est-ce pas ?"},{"a":"hemma","t":"Seulement s’ils sont d’accord. Et les effets ne sont que temporaires."},{"a":"hemma","t":"Et puis, nous les dédommageons très généreusement."},{"a":"elderowen","t":"Bon, peut-être que tu ne fais rien de mal au final."},{"a":"elderowen","t":"Fort bien, je n’ai pas d’objection à ce que tu deviennes championne de la cité."},{"a":"hemma","t":"Nous n’avions pas besoin de votre autorisation... mais merci."},{"a":"elderowen","t":"Et qu’est-ce qui t’amènes dans notre cité, au juste ?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Nous sommes en quête de savoir et de puissance, rien de plus. "},{"a":"hemma","t":"Et nous avons... une tâche à accomplir."},{"a":"elderowen","t":"Tout ça est très vague."},{"a":"hemma","t":"Et ça le restera. Au revoir."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"Je lis une grande tristesse dans ses yeux..."}]},{"id":"hemma_03","i":3,"title":"L’ennemi intérieur","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"herbalist","t":"[...] une botte de racines vivantes encore vertes et un ectoplasme lugubre bien ferme. Autre chose avec ça ?"},{"a":"hemma","t":"Ce sera tout. Nous trouverons le reste au magasin."},{"a":"herbalist","t":"Merci bien, revenez vite !"},{"a":"hemma","t":"<c4>N’oublie pas les serres sinistres...</c4>"},{"a":"hemma","t":"Ah, mais oui. Et une paire de serres sinistres, s’il vous plaît."},{"a":"herbalist","t":"Mais... C’était QUOI, ça ?!"},{"a":"hemma","t":"Ne faites pas attention. Appelez ça un simple passager, si vous voulez."},{"a":"hemma","t":"<c4>Je-veux-sortir-je-veux-sortir-je-veux-sortir-je-veux-sortir-je-veux-sortir.</c4>"},{"a":"hemma","t":"Eurh. Du calme, là-dedans."},{"a":"hemma","t":"Gardez donc la monnaie. Au revoir."},{"a":"herbalist","t":"Euh... merci pour le pourboire... et les cauchemars."}]},{"id":"hemma_a","i":3,"title":"D’un immortel à l’autre","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"donovan","t":"De la racine vivante encore verte ? C’est un choix intéressant."},{"a":"hemma","t":"À quel titre ?"},{"a":"donovan","t":"La racine vivante est un composant puissant, souvent utilisé pour la magie liée à la jeunesse et à la longévité."},{"a":"donovan","t":"Seriez-vous une collègue alchimiste ? En quête de longue vie, peut-être ?"},{"a":"hemma","t":"Êtes-vous en train de demander son âge à une dame ? C’est très... inconvenant."},{"a":"hemma","t":"Nous ne sommes pas alchimiste. Les sacrifices de sang sont bien plus efficaces."},{"a":"donovan","t":"Ah, de la nécromancie ! Un domaine respectable mais souvent incompris."},{"a":"hemma","t":"Pour ce qui est de notre âge... Nous avons cessé de compter il y a un certain temps."},{"a":"donovan","t":"Je vous comprends bien. Au bout de quelques siècles, les décennies passent en un clin d’œil !"},{"a":"donovan","t":"On se sent bien seul, entouré de toutes ces créatures si éphémères, n’est-ce pas ?"},{"a":"hemma","t":"Seule, certainement pas. Il serait prudent de ne pas vous immiscer dans les affaires d’une nécromancienne."},{"a":"donovan","t":"Il va sans dire. Je ne cherchais aucunement à être indiscret. Au revoir !"},{"a":"donovan","t":"Bien étrange, cette nécromancienne... L’aurais-je déjà croisée ?"},{"a":"donovan","t":"... Fairlyn ?"}]},{"id":"hemma_04","i":4,"title":"Exorcisme","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Tout ira bien, Hemma, j’arrive ! Et j’ai Freyja avec moi !"},{"a":"priest","t":"Hemma, c’est bien ça ? Détendez-vous. Laissez l’exorcisme passer en vous."},{"a":"hemma","t":"Nous n’avons pas souvenir de vous avoir demandé de l’aide."},{"a":"hemma","t":"<c4>Dégagez, les morveuses. J’y suis, j’y reste.</c4>"},{"a":"lilu","t":"Aaaah ! Il est en train de prendre le contrôle ! Vite, Freyja !"},{"a":"priest","t":"Mais... Je n’y arrive pas ! Il y a quelque chose qui bloque mes prières."},{"a":"hemma","t":"C’est nous. Nous vous demandons de vous arrêter."},{"a":"priest","t":"Mais... Cet esprit malfaisant, vous l’accueillez de plein gré ?!"},{"a":"hemma","t":"Il est devenu un peu fou avec les années, il faut bien l’admettre."},{"a":"hemma","t":"<c4>C’est moi la victime, ici ! Je veux sortir !</c4>"},{"a":"hemma","t":"Humpf. Il est plus grossier que malfaisant, je peux vous en assurer."},{"a":"hemma","t":"Mais cette affaire ne vous regarde pas. Merci de ne pas vous en mêler, Freyja."},{"a":"priest","t":"Ah, les nécromanciens... Toujours à jouer avec des pouvoirs qu’ils ne comprennent pas vraiment !"},{"a":"lilu","t":"Ça ira ! Je suis sûre qu’elle sait ce qu’elle fait ?"},{"a":"lilu","t":"... Pas vrai ?"}]},{"id":"hemma_05","i":5,"title":"Deux esprits en un","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"hemma","t":"<c4>On dirait que ton petit secret est encore éventé. Prête à fuir la cité ?</c4>"},{"a":"hemma","t":"Tout ça est de ta faute. Si tu étais capable de la fermer, tout serait bien plus facile."},{"a":"hemma","t":"Quoi qu’il en soit, nous ne partons encore. Cette ville a un certain potentiel."},{"a":"hemma","t":"<c4>Très bien. Et si tu me laissais sortir un peu, pour une fois ?</c4>"},{"a":"hemma","t":"Hors de question. Tu es déjà bien assez difficile à contrôler comme ça."},{"a":"hemma","t":"<c4>Je-veux-sortir-je-veux-sortir-je-veux-sortir-je-veux-sortir-je-veux-sortir.</c4>"},{"a":"hemma","t":"Tout ça, c’est pour ton bien que je le fais, Claud."},{"a":"hemma","t":"Essaie de t’en souvenir."}]},{"id":"hemma_06","i":6,"title":"Héritage mensonger","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Fairlyn !"},{"a":"hemma","t":"Oui ?"},{"a":"lilu","t":"Je le savais ! Hemma est un faux nom ! C'est toi le monstre, Fairlyn !"},{"a":"hemma","t":"Ouah. Quelle sournoise petite créature avons-nous là."},{"a":"hemma","t":"C'est vrai. Tu sembles avoir fait tes recherches."},{"a":"hemma","t":"Peut-être que tu as déjà entendu parler d'Ariel le fou ? Ou bien d'Astrid la déchue ?"},{"a":"lilu","t":"...J'ai lu à leur sujet... mais ils ont disparu il y a des décennies ! Il ne peuvent pas être..."},{"a":"hemma","t":"Nous, bien sûr. Malheureusement nous sommes vraiment persécutés et les noms ne doivent pas apparaître..."},{"a":"lilu","t":"Tu es un monstre ! Il faut t'arrêter !"},{"a":"hemma","t":"Et comment comptez-vous faire ça ? « Hemma » est innocent. Qui croirait vos récits farfelus ?"},{"a":"hemma","t":"À moins bien sûr que vous ne comptiez m'arrêter vous-même..."},{"a":"lilu","t":"...Hmm !"}]},{"id":"hemma_07","i":7,"title":"Tranche d'âme","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"hemma","t":"Toujours à rôder dans le coin ?"},{"a":"lilu","t":"Je garde un œil sur toi. Toi et tes monologues suspicieux..."},{"a":"hemma","t":"Ha oui, je te présente Claud. C'est pas son meilleur profil."},{"a":"hemma","t":"<c4>Je veux m'en aller !</c4>"},{"a":"lilu","t":"...Que lui est-il arrivé ?"},{"a":"hemma","t":"Un terrible accident de nécromancie. Un bête accident l'a laissé à moitié mort."},{"a":"hemma","t":"Au vu de nos pêchés sur cette terre, l'au-delà semble effrayant pour nous autres nécromanciens..."},{"a":"hemma","t":"Incapables de sauver son corps, nous avons fait ce que nous avons pu... et nous avons sauvé son âme."},{"a":"lilu","t":"Une tranche d'âme ? Ce sort demande des années de recherche pour préparer un réceptacle approprié..."},{"a":"hemma","t":"En effet. Mais les circonstances nous ont poussé vers l'improvisation."},{"a":"lilu","t":"L'improvisation ? Que voulez-vous dire... vous avez lié l'âme de Claud à la vôtre ?!"},{"a":"lilu","t":"Un corps ne peut pas contenir deux âmes ! Cela entraînerait..."},{"a":"hemma","t":"D'incessantes douleurs. La folie. Bien plus encore que ce que tu imagines."},{"a":"lilu","t":"Hemma... Pourquoi... ? Comment... ?"},{"a":"hemma","t":"C'est simple, Lilu. L'échec... n'est pas une option."}]},{"id":"hemma_08","i":8,"title":"La prime du siècle","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Trop puissante pour un exorcisme... peut-être que l'âme pourrait être liée à autre chose... ?"},{"a":"hemma","t":"Tu es vraiment altruiste. Tu t'intéresses soudainement à la nécromancie ?"},{"a":"lilu","t":"Non ! Je te déteste et tout ce que tu as fait !"},{"a":"lilu","t":"...Je vois ça comme ça. Si ce Claud s'échappe, ça va entraîner de gros problèmes pour tout le monde."},{"a":"lilu","t":"Je t'aide à réparer tes bêtises, rien de plus !"},{"a":"hemma","t":"Une noble intention. Mais comment un simple enfant pourrait-il m'aider ?"},{"a":"lilu","t":"La préparation d'un réceptacle prendrait des décennies de recherche, sans même parler des matériaux..."},{"a":"hemma","t":"Ce ne sera pas un problème. Regarde."},{"a":"lilu","t":"... !! Mais où est-ce que t’as déniché tout ça... ? Il y a même des diamants noirs !"},{"a":"hemma","t":"Ces dernières décennies n'auront pas été en vain. Nous n'avons plus beaucoup de temps."},{"a":"hemma","t":"Il ne nous manque plus qu'un endroit approprié pour mener le rituel. J'ai bien peur qu'un tel lieu n'existe pas."},{"a":"lilu","t":"Bon. L'âme a besoin d'un lien spirituel à la zone, ou le rituel échouera."},{"a":"hemma","t":"<c4>Sinon on pourrait tout simplement libérer ce bon vieux Claud Favius ! Il se fera beaucoup d'amis !</c4>"},{"a":"lilu","t":"Quoi... tu as bien dit Favius ?"}]},{"id":"hemma_09","i":9,"title":"Le château hanté","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"hemma","t":"Voilà un endroit délicieusement terrifiant."},{"a":"lilu","t":"C'est un horrible endroit. Aucune personne saine d'esprit ne devrait venir ici."},{"a":"lilu","t":"Mais plus important encore, d'après mes recherches..."},{"a":"lilu","t":"...Un roi fou de la famille Favius a dirigé la région il y a des siècles."},{"a":"lilu","t":"Peut-être que Claud est un cousin éloigné ? J'espère qu'il n'a rien à voir avec la chute de ce royaume..."},{"a":"hemma","t":"...On peut le sentir. Nous sommes connectés à cet endroit. C'est bon."},{"a":"hemma","t":"Je te dois beaucoup, Lilu. Mais tu dois désormais nous laisser."},{"a":"lilu","t":"Hemma... Bonne chance."}]},{"id":"hemma_10","i":10,"title":"Jusqu'à ce que la mort nous sépare","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"hemma","t":"Un lieu sombre, hanté et isolé, qui déborde d'énergie nécromantique..."},{"a":"hemma","t":"Combien de temps avons-nous cherché un tel endroit ?"},{"a":"hemma","t":"Il nous faut désormais un réceptacle adapté..."},{"a":"hemma","t":"Pas besoin de parler. Nous savons exactement ce que tu veux."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"...L'armure du roi fou lui-même, éternellement liée à cet endroit."},{"a":"hemma","t":"<c1>Tranche d'âme !</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Euh... Nous... ou moi... ?"},{"a":"hemma","t":"J'avais oublié ce sentiment de solitude..."},{"a":"hemma","t":"J'ai enduré une éternité pour te sauver. Je sais que tu aurais fait exactement la même chose pour moi."},{"a":"hemma","t":"De braves aventuriers viendront certainement un jour. Affronte-les et par le carnage, soigne ton existence torturée."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Adieu, amour. Mais seule la mort nous séparera véritablement."}]},{"id":"hemma_epilogue","i":11,"title":"Épilogue","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>HÉÉÉÉÉ !!! COMMENT OSEZ-VOUS MARCHER SUR MES TERRES ?</c4>"},{"a":"sia","t":"...Quel adversaire agaçant !"},{"a":"Castle_Boss","t":"<c4>MOUAHAHAHAHA FAIBLES MORTELS !</c4>"},{"a":"argon","t":"Dame Sia ! Rudo ! Nous devons battre en retrait !"},{"a":"rudo","t":"Jamais ! Je ne céderai pas un centimètre de terrain !"},{"a":"yami","t":"J'ai trouvé une sortie. Vite !"},{"a":"rudo","t":"Bon ! Je reviendrai, boîte de conserve ! Tu m'entends ?"},{"a":"Castle_Boss","t":"<c4>REVENEZ QUAND VOUS SEREZ CAPABLES DE VOUS BATTRE !</c4>"},{"a":"Castle_Boss","t":"<c4>DITES À VOS PLUS GRANDS HÉROS QUE LE ROI TYRAN LES ATTEND !</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Une apprentie précoce","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Alors, Pollux, qu’est-ce que tu penses de mon nouveau sort ? Parfait, hein ?"},{"a":"lilu","t":"Mais oui ! Cette fois on va l’avoir haut la main, c’est sûr."},{"a":"herbalist","t":"Bonjour, Lilu. Tu viens pour la livraison de racine vivante de la semaine ?"},{"a":"lilu","t":"Oui. Merci, Maribelle."},{"a":"herbalist","t":"C’est une belle commande, cette fois. Qu’est-ce qu’il fait donc de toutes ces racines, ton maître ?"},{"a":"lilu","t":"Pour être honnête, il y en a à peu près la moitié pour moi. Je m’entraîne dur !"},{"a":"herbalist","t":"Ah ? Et sur quoi ?"},{"a":"lilu","t":"Les sorts de soins. J’ai passé toute la semaine dernière à soigner les plaies et les bosses à la salle d’entraînement."},{"a":"herbalist","t":"Les héros doivent être bien contents de t’avoir."},{"a":"herbalist","t":"Et... Argon aussi, hein ?"},{"a":"lilu","t":"!!"},{"a":"lilu","t":"Il faut que je me sauve ! Merci !"}]},{"id":"lilu_02","i":2,"title":"Tristes nouvelles","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Voilà, maître Grimar. Les racines vivantes pour cette semaine."},{"a":"wizard","t":"Merci, Lola. Et voici tes devoirs pour aujourd’hui."},{"a":"lilu","t":"Oh, un recueil de magie ! C’est sur les sorts de soins ?"},{"a":"lilu","t":"« Manuel de malédiction à l’usage des mécréants »... ?"},{"a":"lilu","t":"Mais c’est bien trop avancé pour moi ! Il y a même tout un chapitre sur les imprécations !"},{"a":"wizard","t":"De malédiction... ?"},{"a":"wizard","t":"Hum, les malédictions..."},{"a":"lilu","t":"Maître ?"},{"a":"wizard","t":"Il y a trente-cinq ans ce jour, j’ai... j’ai..."},{"a":"lilu","t":"Maître Grimar ?"},{"a":"wizard","t":"J’ai oublié. Euh, et qui êtes-vous ?"},{"a":"lilu","t":"Lilu, votre apprentie. Des fois, vous m’appelez Lola."},{"a":"lilu","t":"Ce n’est pas grave. Je vais étudier ce recueil, merci."}]},{"id":"lilu_03","i":3,"title":"Cerveau embrouillé","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"... Ajouter une pincée de Poussière d'argent et... voilà !"},{"a":"lilu","t":"Comme ça brille ! Pas mal, hein Pollux ?"},{"a":"lilu","t":"À en croire le Manuel de malédiction à l’usage des mécréants, cette potion devrait..."},{"a":"wizard","t":"Lola, c'est quoi, tout ce grabuge ? J'essaie de dormir !"},{"a":"lilu","t":"Maître Grimar ! Merci pour votre livre, j'ai préparé une potion très complexe ! Elle devrait..."},{"a":"wizard","t":"Tu as fait quoi ?!"},{"a":"wizard","t":"Eh bien, donne-moi ça ! Voyons le goût qu'elle a !"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Maître Grimar ?"},{"a":"wizard","t":"Lilu ! Il f-f-faut me li-libérer ! So-Sortez-moi de ce esp-p-prit complètement n-n-n... n-n-niais !"},{"a":"lilu","t":"M... maître Grimar ! Vous allez bien ?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"*Rot* Un petit goût fruité !"},{"a":"wizard","t":"Pas mal, Lola. Eh bien maintenant, termine tes corvées."},{"a":"lilu","t":"... Ce n'était PAS normal."}]},{"id":"lilu_a","i":3,"title":"Un tas de vieilleries","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"lilu","t":"Grimar, vous ne m’aviez pas dit que vous aviez un deuxième <c1>registre de collection</c1> !"},{"a":"wizard","t":"Un <c1>registre de collection</c1>... ? Oui, ça me dit quelque chose..."},{"a":"lilu","t":"Ouah, et celui-là est vraiment bien rempli ! <c1>Damoclès</c1>... <c1>Citadelle d’ambre</c1>..."},{"a":"lilu","t":"« <c1>Grande baguette de Grimar</c1> » ? C’est vous qui lui avez donné ce nom ?"},{"a":"lilu","t":"Le nombre de pages est impressionnant ! Vous deviez être un sacré collectionneur."},{"a":"sundragon","t":"Ah, ça, il l’était !"},{"a":"wizard","t":"Sondra, mon vieil ami, c’est bien toi ?"},{"a":"lilu","t":"Ouah, mais vous vous connaissez ?"},{"a":"sundragon","t":"Mais oui. Jeune, le petit Grimar était inséparable de son registre de collection."},{"a":"sundragon","t":"Je crois que ça lui avait valu un titre prestigieux auprès de ses compagnons humains... Comment disaient-ils, déjà ? « Ringard » ?"},{"a":"lilu","t":"Aïe."},{"a":"sundragon","t":"C’est à cette époque que nous nous sommes rencontrés, alors qu’il cherchait les objets les plus rares, et ensemble, nous avons créé le <c1>cratère à fusion</c1>."},{"a":"sundragon","t":"Il passait ses jours et ses nuits à fusionner les objets par centaines... et encore plus quand la lune était pleine !"},{"a":"lilu","t":"Tant d’efforts... et pourtant, sa collection n’est pas encore complète."},{"a":"lilu","t":"Je vais trouver comment vous guérir, maître Grimar, je vous le promets ! Vous devez finir votre œuvre !"},{"a":"sundragon","t":"Le temps est bien cruel avec les humains. Bonne chance, ma petite."}]},{"id":"lilu_04","i":4,"title":"La fin d'une noble lignée","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Il y a quelque chose d’étrange avec maître Grimar..."},{"a":"lilu","t":"Cette voix... On aurait dit que quelqu’un parlait à l’intérieur de lui !"},{"a":"lilu","t":"Ça pourrait être un sortilège de transmutation très complexe ?"},{"a":"lilu","t":"Ou peut-être même..."},{"a":"leather","t":"Dis donc, Lilu ! Il y a eu un problème à la fête du roi !"},{"a":"lilu","t":"Tamas ? Qu'est-ce qu'il se passe ?"},{"a":"leather","t":"Une personne se serait introduite dans le château. Franchement, ça fout les jetons !"},{"a":"lilu","t":"Un envahisseur... ! Oh non, c'est le premier jour d'Argon en tant que chevalier !"},{"a":"lilu","t":"Merci Tamas, je dois y filer !"},{"a":"lilu","t":"Oh non... ! Qu'est-ce qu'il se passe ici !?"},{"a":"lilu","t":"Argon, où es-tu !?"},{"a":"king","t":"Aaargh..."},{"a":"lilu","t":"VOTRE MAJESTÉ !? Vous allez bien ?"},{"a":"king","t":"Aahh... Ma vie, si précieuse... qui me quitte..."},{"a":"lilu","t":"On est mal... !"},{"a":"lilu","t":"Concentre-toi Lilu ! Rappelle-toi de la formation du sage !"},{"a":"lilu","t":"Votre majesté Reinhold, sire ! Tenez bon ! <c1>Soigner</c1> !"},{"a":"king","t":"C'est inutile... S'il vous plaît... préservez mon magnifique cadavre..."},{"a":"lilu","t":"Aucun effet..."},{"a":"lilu","t":"Oh non... c'est peut-être... du poison ?"},{"a":"lilu","t":"... Comme mes parents... ! Cette fois, je réussirai ! Impossible d'échouer !"},{"a":"lilu","t":"<c1>Anti-poison supérieur !</c1>"},{"a":"king","t":"...Aaaah... Hein ?"},{"a":"lilu","t":"Votre majesté ! Comment allez-vous ?"},{"a":"lilu","t":"Attendez une minute... Cette coupe vous a protégé du shuriken ! Vous n'êtes pas blessé du tout !"},{"a":"king","t":"Ah bon, vraiment ? J'ai peut-être un peu surréagi."},{"a":"king","t":"Après tout, le décès d'un monarque, c'est un événement important."},{"a":"lilu","t":"Argh ! Reinhold, sire !"}]},{"id":"lilu_05","i":5,"title":"Cadeau empoisonné","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Pfouh, ça n’est pas passé loin... Je crois."},{"a":"lilu","t":"Si Reinhold a vraiment été empoisonné... je crois que je n’aurais pas pu le sauver."},{"a":"lilu","t":"Il faut que je recentre mes efforts. Je veux que personne n’ait à subir les mêmes pertes que moi."},{"a":"lilu","t":"Madame Sia !"},{"a":"sia","t":"Ah, notre héroïne du moment ! N’ayez crainte, un chevalier a été envoyé se charger de l’intruse."},{"a":"lilu","t":"(Un chevalier ? Bonne chance, Argon !)"},{"a":"sia","t":"Merci d’avoir... sauvé notre roi, malgré les circonstance."},{"a":"lilu","t":"Ce n’est rien ! Mais si ça devait se reproduire, je ne suis pas sûre que je pourrais aider..."},{"a":"lilu","t":"Dites, madame Sia, vous vous y connaissez, en poison ?"},{"a":"sia","t":"Bien sûr. L’aconitum, qu’on appelle aussi aconit tue-loup, est une plante terriblement meurtrière."},{"a":"sia","t":"Mais personnellement, un de mes préférés est la ricine. Discrète, mortelle et facilement disponible."},{"a":"lilu","t":"Hum... et pour ce qui est de les guérir."},{"a":"sia","t":"Ah. Je dois dire que je ne me suis jamais beaucoup occupée de ça."},{"a":"lilu","t":"Oubliez la question..."}]},{"id":"lilu_06","i":6,"title":"Le maître et l’élève","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Me voilà de retour, maître Grimar !"},{"a":"wizard","t":"Ah, bon retour, Lola."},{"a":"lilu","t":"Vous vous rendez compte ? Le roi a failli être assassiné !"},{"a":"wizard","t":"Vraiment..."},{"a":"lilu","t":"Un assassin a surgi de nulle part et l’a attaqué avec un shuriken !"},{"a":"lilu","t":"Il gisait au sol, alors je me suis élancée à son secours !"},{"a":"wizard","t":"Ah, et euh... Qui êtes-vous, déjà ?"},{"a":"lilu","t":"Ah, oui, votre maladie... Il faut que je retourne à mes recherches là-dessus."},{"a":"lilu","t":"Il se pourrait que ce soit un poison aussi."},{"a":"lilu","t":"Voyons voir. Grimar est extrêmement vieux..."},{"a":"lilu","t":"Qu’est-ce que tu en penses, Pollux ?"},{"a":"lilu","t":"C’est vrai, on devrait interroger les habitants !"},{"a":"lilu","t":"Peut-être que certains des plus âgés se rappelleront à quoi s’occupait Grimar plus jeune."}]},{"id":"lilu_07","i":7,"title":"Savoir ancestral","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Maître Théodore !"},{"a":"master","t":"Ah, mais c’est Lilu ! Qu’est-ce que je peux faire pour toi aujourd’hui ?"},{"a":"lilu","t":"Je me demandais si vous pouviez me parler de Grimar quand il était jeune."},{"a":"lilu","t":"Vu que vous êtes, euh... vieux."},{"a":"master","t":"Ha ha ha ! Mais bien sûr."},{"a":"master","t":"Le vieux Grimar a toujours été un petit peu excentrique."},{"a":"master","t":"Mais quand j’étais un jeunot, je me souviens qu’il avait l’esprit beaucoup plus vif. Il était même aussi bon que moi aux échecs."},{"a":"master","t":"Mais après son excursion aux ruines de Chronos... Il n’a plus jamais vraiment été le même, maintenant que j’y pense."},{"a":"lilu","t":"Les ruines de Chronos ! C’est un endroit vraiment dangereux."},{"a":"lilu","t":"C’est toute une civilisation qui s’est effondrée à cause de ses recherches sur la magie temporelle."},{"a":"lilu","t":"L’endroit est plein d’anomalies temporelles ! Qu’est-ce que Grimar avait à gagner à se rendre là-bas ?"},{"a":"lilu","t":"Tu as raison, Pollux. C’est la seule piste qu’on a. Il va falloir aller enquêter !"},{"a":"lilu","t":"Mais pour ça, il nous faudrait une escorte... On demande à Argon ?"},{"a":"lilu","t":"Non ! Et s’il se fait changer en vieillard par un tourbillon temporel ? Ou le rend comme Grimar..."},{"a":"lilu","t":"Je ne vois qu’une autre personne qui pourrait nous aider."},{"a":"lilu","t":"Pollux, ça ne va pas être facile, mais il faut essayer."},{"a":"lilu","t":"Merci, Théodore ! Vous m’avez rendue un beau service !"},{"a":"master","t":"Mais de rien, Lilu. À bientôt."},{"a":"master","t":"..."},{"a":"master","t":"Mais c’est qu’il n’est pas bête du tout, ce hibou !"}]},{"id":"lilu_08","i":8,"title":"Cause commune","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Ohé, monsieur Rudo ! Ne partez pas, j’ai quelque chose à vous demander !"},{"a":"rudo","t":"Dégage, gamine. Ça ne m’intéresse pas."},{"a":"rudo","t":"Va jouer avec ton hibou !"},{"a":"lilu","t":"Je sais bien que vous n’aimez pas les magiciens... mais j’ai vraiment besoin de votre aide !"},{"a":"lilu","t":"J’ai besoin d’entrer dans les ruines de Chronos, mais je ne peux pas y aller seule. "},{"a":"rudo","t":"Et pourquoi tu ne demandes pas à ton preux chevalier, le petit Argon ?"},{"a":"lilu","t":"Euh, il est, euh... Il est occupé ailleurs en ce moment."},{"a":"lilu","t":"Mais bon, on dirait que ça ne sert à rien de vous demander."},{"a":"rudo","t":"Exactement."},{"a":"tavern","t":"Oh, mais quel dommage, trésor."},{"a":"tavern","t":"Il paraît que le seigneur cyclope des ruines de Chronos n’a encore jamais été vaincu en combat singulier."},{"a":"tavern","t":"Il va falloir trouver un guerrier absolument formidable pour escorter la petite Lilu !"},{"a":"rudo","t":"Tu as dit... jamais vaincu ?"},{"a":"rudo","t":"Pfff. D’accord, tu m’as eu. Il y aura beaucoup de trucs à détruire ?"},{"a":"lilu","t":"Oh, plein, c’est sûr !"},{"a":"lilu","t":"Parce qu’il faut que je trouve la source du flux temporel qui émane des cristaux et que j’isole..."},{"a":"rudo","t":"Abrège. Les trucs à détruire ?"},{"a":"lilu","t":"(...) Et il y aura plein de monstres et de cristaux magiques à détruire."},{"a":"rudo","t":"Bon, c’est vendu. Tu auras une dette envers moi."},{"a":"lilu","t":"C’est merveilleux ! Merci infiniment, monsieur Rudo !"},{"a":"rudo","t":"Tu me remercieras quand on sera rentrés. Ça ne va pas être une mince affaire."},{"a":"lilu","t":"Je serai là pour vous soigner s’il y a trop de monstres !"},{"a":"rudo","t":"Humpf. Ça m’étonnerait."},{"a":"lilu","t":"Et merci Naya, aussi !"},{"a":"tavern","t":"Mais de rien, trésor."}]},{"id":"lilu_09","i":9,"title":"Monde miroir","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"rudo","t":"Je vais occuper le Cyclope ! Vous, avancez !"},{"a":"rudo","t":"Par ici, Clope ! Viens manger la bonne avoine !"},{"a":"lilu","t":"Compris ! Bonne chance !"},{"a":"lilu","t":"La voilà... La Chambre du Temps. Et si j’en crois mes recherches..."},{"a":"lilu","t":"Ce bassin doit être lié à une chronologie fragmentée !"},{"a":"lilu","t":"Un univers parallèle où Chronosville est encore prospère..."},{"a":"lilu","t":"Regarde, Pollux ! Si on fixe l’eau... on voit quelque chose !"},{"a":"lilu","t":"Les habitants de Chronos semblent mener une vie normale, quelque part ailleurs..."},{"a":"lilu","t":"Hé... J’ai la berlue ou ce type nous fait signe ?"},{"a":"lilu","t":"On dirait... Grimar ?"}]},{"id":"lilu_10a","i":10,"title":"Mal des Ans sans fin","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Grimar ! Buvez ça !"},{"a":"wizard","t":"Hein ? Ça me rappelle quelque chose..."},{"a":"lilu","t":"C’est une blonde spéciale brassée à l’eau de Chronos..."},{"a":"wizard","t":"... Stabilisée par une double infusion de fils du destin ?"},{"a":"lilu","t":"... puis matérialisée à l’aide de distillat d’ectoplasme."},{"a":"wizard","t":"Avec une pincée de corail des profondeurs, pour le goût !"},{"a":"wizard","t":"Magnifique travail, Lilu. Tu ne pouvais pas faire plus honneur à ton maître."},{"a":"lilu","t":"G-Grimar... Vous êtes revenu à la normale ! Ça a marché !"},{"a":"wizard","t":"Quelle étrange expérience. J’ai l’impression qu’un brouillard vient de se dissiper dans mon cerveau..."},{"a":"lilu","t":"J’ai une vague idée du fonctionnement de la potion, mais... quelque chose ne colle pas."},{"a":"lilu","t":"On vous a vu dans le bassin ! Dans la chronologie fragmentée !"},{"a":"wizard","t":"Ho ho ! Tiens donc ? J’ai une théorie là-dessus..."},{"a":"wizard","t":"Pollux, mon bon. Peux-tu aller chercher ce vieil Owen ? Les explications risquent d’être longues..."}]},{"id":"lilu_10b","i":11,"title":"Théorème de chronoséparation","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"elderowen","t":"Ma parole, mon vieux ! En voilà, un récit !"},{"a":"lilu","t":"J’ai moi-même du mal à y croire... Grimar, survivant de Chronosville ?"},{"a":"wizard","t":"Quand le sort temporel a mal fonctionné, toute cette ville s’est retrouvée projetée dans une autre chronologie."},{"a":"elderowen","t":"Je m’en souviens comme si c’était hier. Une ville tout entière, partie en un clin d’œil !"},{"a":"elderowen","t":"Nous n’avons trouvé parmi les ruines qu’un enfant seul, abandonné..."},{"a":"lilu","t":"Grimar, n’est-ce pas ? J’ai du mal à vous imaginer enfants, tous les deux..."},{"a":"elderowen","t":"Ho ho ! Nous sommes vite devenus amis, n’est-ce pas ?"},{"a":"wizard","t":"En effet. J’ai fait des études de sorcellerie pour enquêter moi-même sur cet étrange événement."},{"a":"wizard","t":"Si Lilu a bien vu ce qu’elle affirme, je crois qu’il existe un autre Grimar."},{"a":"lilu","t":"L’autre Grimar que nous avons vu... Vous existez toujours dans l’autre chronologie ?"},{"a":"wizard","t":"Il faut croire. Il n’y a d’abord pas eu de conséquences, mais..."},{"a":"wizard","t":"En grandissant, notre vécu et notre personnalité ont commencé à s’écarter."},{"a":"lilu","t":"D’où un paradoxe magique qui a pesé de plus en plus sur votre esprit..."},{"a":"lilu","t":"Je comprends ! En buvant une potion des ruines de Chronos, vous reprenez prise avec cette autre chronologie !"},{"a":"wizard","t":"C’est ma théorie. Je suis sûr que l’autre Grimar en est conscient aussi."},{"a":"lilu","t":"Pfff... C’est un peu dur à assimiler. Le sommeil porte conseil, comme on dit... Tu viens, Pollux ?"},{"a":"elderowen","t":"Quant à nous, mon vieux Grim, je crois que nous avons beaucoup de choses à rattraper !"},{"a":"wizard","t":"Tu peux parler, vieille baderne ! Je ne me suis jamais senti aussi jeune !"}]},{"id":"lilu_epilogue","i":12,"title":"Épilogue","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Bonjour, Grimar ! Voici une nouvelle recette. Elle devrait être un peu plus durable !"},{"a":"wizard","t":"Remarquable amélioration ! Tes parents seraient fiers."},{"a":"lilu","t":"... Si seulement j’avais étudié l’alchimie un peu plus tôt..."},{"a":"wizard","t":"Je partage ce sentiment. Si j’étais maître de mes fonctions, peut-être..."},{"a":"lilu","t":"... Tout va bien. J’ai décidé de me tourner vers l’avenir. De m’améliorer pour épargner ce sort à autrui."},{"a":"lilu","t":"... C’est sûrement ce que mes parents auraient voulu."},{"a":"wizard","t":"Que tu as grandi... C’est à peine si je te reconnais."},{"a":"wizard","t":"D’ailleurs... Qui es-tu, déjà ?"},{"a":"lilu","t":"Oh non ! L’effet se dissipe déjà ! Il faut que je..."},{"a":"wizard","t":"Ho ho ho ! Je plaisante. Je sens que cette fois, c’est la bonne."},{"a":"wizard","t":"Mais tant que j’ai les idées claires : que dirais-tu d’apprendre un peu de magie ?"},{"a":"wizard","t":"J’ai encore quelques tours dans mon sac !"},{"a":"lilu","t":"Oh ! Pourquoi pas Polymorphose ? J’ai très envie d’apprendre ça !"}]}]},{"id":"malady","name":"Maladie","chapters":[{"id":"malady_01","i":1,"title":"Gravé dans la pierre","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Quête terminée ! Les enfants perdus ont été trouvés et sauvés !"},{"a":"argon","t":"Les ruines de Chronos ne sont vraiment pas un endroit sûr pour jouer."},{"a":"argon","t":"Je suppose que je devrais m'en aller, moi aussi !"},{"a":"malady","t":"... J'espère que ces méchants troubelins me laisseront tranquille aujourd'hui."},{"a":"argon","t":"Bonjour, mademoiselle ! Vous êtes perdue, vous aussi ?"},{"a":"malady","t":"Ne... N'approchez pas plus !"},{"a":"argon","t":"Hein ?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Si vous croisez mon regard, cela vous transformera en pierre à jamais. C'est la malédiction de Méduse."},{"a":"malady","t":"Pourtant... vous avez l'air gentil."},{"a":"malady","t":"... Je suis désolée."}]},{"id":"malady_02","i":2,"title":"Celui en marbre","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"*Gnnn*... Owen... l’ancien..."},{"a":"elderowen","t":"Lilu ! Qu’est-ce que tu fais, à traîner cette statue ?"},{"a":"elderowen","t":"Une statue... d'Argon ?"},{"a":"lilu","t":"Han... Han... Cette statue EST Argon !"},{"a":"elderowen","t":"Oh, mince. Il a été pétrifié, c'est ça ?"},{"a":"lilu","t":"Je crois. Je l'ai trouvé dans cet état dans les ruines de Chronos."},{"a":"lilu","t":"Rudo m'a aidée à le transporter sur une partie du chemin, heureusement !"},{"a":"elderowen","t":"Quel pétrin ! Tu vas pouvoir le soigner ?"},{"a":"lilu","t":"Probablement ! Mais les ingrédients sont rares, ça ne sera pas facile."},{"a":"lilu","t":"Je vais rassembler les citadins et le marchand aussi ! Prends soin d'Argon !"},{"a":"elderowen","t":"Bien sûr. J'espère que ça ne te gêne pas de servir de décoration de pelouse un moment, mon garçon."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Oh, maudits pigeons ! Du balai !"}]},{"id":"malady_03","i":3,"title":"Œil pour œil","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"... Cette liane luxuriante devrait être assez ancienne pour que ça fonctionne. Mais, il n'en reste pas beaucoup..."},{"a":"lilu","t":"Ensuite... du sang de Méduse. Ce ne sera pas simple."},{"a":"malady","t":"Heu..."},{"a":"lilu","t":"Haaa ! Un monstre !"},{"a":"malady","t":"... Cet humain, avant, c'est un ami à vous ?"},{"a":"lilu","t":"Argon ? Minute, c'est VOUS qui avez fait ça ?"},{"a":"lilu","t":"Bon, ça facilite BIEN les choses. J'ai justement aussi besoin de sang de Méduse..."},{"a":"malady","t":"Non, pitié ! Je ne vous veux aucun mal."},{"a":"lilu","t":"C'est ça ! Vous l'avez pétrifié !"},{"a":"malady","t":"... Désolée. J'avais peur, et nos regards se sont croisés."},{"a":"malady","t":"Je ne savais pas comment réagir... Personne n'a été gentil avec moi jusqu'ici."},{"a":"lilu","t":"... Mince, ça n'a pas dû être facile."},{"a":"malady","t":"Si vous avez besoin de sang... Je vous en fournirai."},{"a":"malady","t":"En échange, s'il vous plaît... laissez-moi vous accompagner. J'aimerais lui présenter mes excuses."},{"a":"lilu","t":"... Bon. Ça ne me plaît pas, mais si j'avais été pétrifiée, je ne crois pas que Donovan nous aurait sauvés."},{"a":"lilu","t":"Je vous surveille. Et vous, évitez de me regarder !"},{"a":"malady","t":"Oui. Merci."}]},{"id":"malady_04","i":4,"title":"En chair et à nouveau en pierre","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Terminé ! Cette potion devrait faire l'affaire. Plic ploc !"},{"a":"argon","t":"Aaaah ! Ça fait du bien de s'étirer !"},{"a":"argon","t":"Minute, que s'est-il passé ?"},{"a":"lilu","t":"Maladie, ici présente, t'a pétrifié par accident et voulait s'en excuser."},{"a":"malady","t":"B-Bonjour. Vraiment désolée. Je ne voulais pas..."},{"a":"argon","t":"Oh, tout va bien ! Je me sens en pleine forme ! Peut-être un peu ankylosé."},{"a":"argon","t":"Tu t'appelles Maladie ? Moi c'est Argon, ravi de te rencontrer !"},{"a":"argon","t":"Hé, ton bandeau a glissé. Laisse-moi t'aider à le remettre en place !"},{"a":"lilu","t":"Argon ! Non !"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon... Je vais devoir lui faire un cours sur les Méduses..."},{"a":"malady","t":"Oh non ! Je suis désolée !"},{"a":"lilu","t":"Ne le sois pas. C'est de sa faute cette fois."},{"a":"malady","t":"J-Je suis prête pour un autre prélèvement de sang..."},{"a":"lilu","t":"Je ne connais pas bien la physiologie de la Méduse, mais tu devrais attendre quelques jours entre deux prises de sang."},{"a":"lilu","t":"En attendant, reste ici. Ce n'est pas prudent de sortir quand tu es affaiblie."},{"a":"lilu","t":"Même si, avec tes... pouvoirs, il vaudrait peut-être mieux demander à Owen l’ancien avant..."},{"a":"malady","t":"Oui."}]},{"id":"malady_05","i":5,"title":"Bon retour parmi nous","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Owen l’ancien, nous sommes de retour !"},{"a":"elderowen","t":"Argon a été soigné ? Excellente nouvelle !"},{"a":"lilu","t":"Pas... tout à fait. Mais..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"Par la déesse ! Une Méduse, ici ?"},{"a":"lilu","t":"C'est Maladie. Elle a aidé à soigner Argon !"},{"a":"lilu","t":"Elle va devoir rester ici quelques jours pour que nous puissions le soigner... à nouveau."},{"a":"elderowen","t":"Je vois. Je ne ressens aucune méchanceté en vous. Pardon pour ma réaction, Maladie."},{"a":"malady","t":"À cause de ma malédiction, tout le monde me déteste, même les autres monstres. J'ai l'habitude."},{"a":"elderowen","t":"Les portes de la ville sont toujours ouvertes à ceux qui sont prêts à travailler pour le bien commun."},{"a":"malady","t":"... Vraiment ?"},{"a":"elderowen","t":"Tant que tes yeux sont couverts, je n'y vois aucun mal."},{"a":"elderowen","t":"Maladie... J'espère que tu auras plus de chance ici que parmi les tiens."},{"a":"malady","t":"Merci... Jamais on ne m'a bien accueillie avant, où que ce soit..."},{"a":"elderowen","t":"Tu devrais aller voir le marchand sans tarder. Il a toujours du travail pour les jeunes gens tels que toi."},{"a":"lilu","t":"Parfait ! Tu pourrais faire des quêtes avec nous !"},{"a":"malady","t":"Je vais faire ça... Merci Lilu et Owen."}]}]},{"id":"polonia","name":"Polonia","chapters":[{"id":"polonia_01","i":1,"title":"Marin d’eau dure","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho, moussaillons !"},{"a":"polonia","t":"Vous avez déjà rêvé d’écumer les sept mers à bord d’un fringant navire ?"},{"a":"polonia","t":"Moi, le capitaine Polonia Del Monte, recrute un nouvel équipage !"},{"a":"polonia","t":"Moi la digne fille du légendaire capitaine pirate Baross Del Monte, je vous promets aventures et richesses !"},{"a":"argon","t":"Capitaine Polonia, c’est ça ?"},{"a":"polonia","t":"Ouaip. Ça t’intéresse ? Un solide gaillard comme toi ferait une belle prise."},{"a":"argon","t":"Euh... Gaillard ?"},{"a":"argon","t":"Non, euh, pas vraiment. Je suis Argon, un apprenti chevalier."},{"a":"argon","t":"La piraterie est illégale, voyez-vous. Alors rendez-vous et suivez-moi sans faire d’histoires, je vous prie."},{"a":"polonia","t":"Mille millions de mille sabords ! Une saleté de chevalier..."},{"a":"polonia","t":"C’est que, euh, je suis une pirate légale. Comme l’autre marin d’eau douce, là... Robin des Forêts."},{"a":"polonia","t":"Je vole aux riches pour donner aux pauvres !"},{"a":"argon","t":"Oh, mais ça paraît très noble. Bon, ça me va, alors. Vous êtes libre !"},{"a":"polonia","t":"Pfiouh..."},{"a":"tavern","t":"Encore une journée difficile, hein ?"},{"a":"polonia","t":"Arrh. C’est une rude vie, la vie de matelot."}]},{"id":"polonia_02","i":2,"title":"L’histoire de Del Monte","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"tavern","t":"Ça ne recrute plus aujourd’hui, Polonia ?"},{"a":"polonia","t":"À quoi bon. Ma carrière de capitaine pirate est un échec, et je ne parle même pas de faire honneur au nom Del Monte."},{"a":"tavern","t":"Ce fameux Baross Del Monte... C’était votre grand-père, c’est ça ?"},{"a":"polonia","t":"Ouaip ! Une légende parmi les légendes ! Mais les temps modernes ne réussissent pas aux pirates."},{"a":"polonia","t":"De nos jours, tous les navires marchands ont des détecteurs magiques dernier cri pour éviter les flubustiers."},{"a":"polonia","t":"Mais Baross s’en moquait bien, lui. Protection magique ou pas, il surgissait des brumes sans crier gare !"},{"a":"polonia","t":"Il détroussait ses proies jusqu’à l’os avec son rire tonitruant comme seule carte de visite."},{"a":"polonia","t":"Même quand tous les autres pirates ont pris leur retraite, il a continué à écumer les mers pendant des décennies !"},{"a":"tavern","t":"C’est un sacré héritage à porter !"},{"a":"polonia","t":"Ouaip ! Et après chaque voyage, il trouvait toujours le temps de rendre visite à sa petite-fille pour lui narrer ses grandes aventures..."},{"a":"polonia","t":"« Hissez le pavillon noir ! Armez les canons ! Tous à sabord, parés à l’abordage ! »"},{"a":"tavern","t":"Sabord... ? On ne dit pas « babord », plutôt ?"},{"a":"polonia","t":"Arrh ! Calamité ! Je n’suis qu’un marin d’eau douce avec un joli costume qui fait de son mieux pour causer comme un pirate."},{"a":"polonia","t":"Et puis, qui a déjà vu un pirate sans navire, hein ?"},{"a":"tavern","t":"Pas de navire, hein ? C’est peut-être par là qu’il faut commencer."},{"a":"polonia","t":"Hein ?"},{"a":"tavern","t":"Un capitaine sans navire aura bien du mal à se dénicher un équipage."},{"a":"tavern","t":"Mais si c’est un bateau que vous cherchez, je connais l’homme qu’il vous faut."},{"a":"polonia","t":"Vraiment ?"},{"a":"polonia","t":"Je veux dire... Par ma barbe, grand merci, tavernière ! Le capitaine Polonia a une dette envers toi !"},{"a":"tavern","t":"Oh, j’y compte bien, croyez-moi."}]},{"id":"polonia_03","i":3,"title":"Menés en bateau","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"carpenter","t":"Construire un bateau entier ?!"},{"a":"polonia","t":"Ouaip. C’est dans tes cordes ?"},{"a":"carpenter","t":"Carrément ! Ce sera mon chef-d’œuvre ! Montrez-moi les plans."},{"a":"carpenter","t":"Hum... Plutôt complexe. Et ces gribouillis, qu’est-ce que c’est ?"},{"a":"polonia","t":"C’est moi qui ai écrit. J’ai jamais appris à lire."},{"a":"carpenter","t":"Ah, voilà qui explique certaines choses. Mais ces plans suffiront amplement."},{"a":"polonia","t":"Yo ho ho ! Ce sera le plus fier navire des mers depuis Baross et le Bonaventure !"},{"a":"carpenter","t":"Mais il y a aussi la question du budget. Vous êtes sûre d’avoir les moyens ?"},{"a":"polonia","t":"Ouaip. Les doublons, ce sera pas un problème. Occupez-vous de mon bateau, je m’occupe de votre butin."}]},{"id":"polonia_a","i":3,"title":"Jambe de quoi ?","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"polonia","t":"Ohé, belle moussaillonne. Tu es guérisseuse, c’est bien ça ?"},{"a":"priest","t":"Oui ! Je suis Freyja, la prêtresse d..."},{"a":"polonia","t":"Tranche-moi la jambe."},{"a":"priest","t":"Pardon ?"},{"a":"polonia","t":"Je te dis de me trancher la jambe !"},{"a":"priest","t":"Bonté divine, mais non ! Qui pourrait demander une chose pareille ?"},{"a":"polonia","t":"Je suis une pirate ! Qui pourrait imaginer une pirate sans une jambe de bois ?"},{"a":"polonia","t":"Tranche-moi donc la jambe et raccommode-la avec ta super magie !"},{"a":"priest","t":"Hors de question. J’ai prêté serment à la déesse de ne jamais faire de mal à un être humain."},{"a":"polonia","t":"Arrh, empotés de marins d’eau douce ! Alors tu n’auras pas un traître doublon !"},{"a":"priest","t":"Vraiment étrange, cette fille..."}]},{"id":"polonia_04","i":4,"title":"La part du capitaine","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Arrh, ces yétis ont les poches pleines de trésors ! Je vais payer le bateau en un rien de temps !"},{"a":"leather","t":"Salut, me voilà. Qu’est-ce qu’il faut faire, alors ?"},{"a":"polonia","t":"D’abord, tu m’appelles capitaine Polonia, moussaillon !"},{"a":"leather","t":"Pas de problème, cap. Qu’est-ce qu’il faut que je fasse ?"},{"a":"polonia","t":"T’as apporté ton chariot ? Ton boulot, c’est de transporter le butin pendant que moi, je dévalise les yétis."},{"a":"leather","t":"Houlà, cap. Vous volez ces belles créatures à fourrure ?"},{"a":"polonia","t":"Ouaip. Pour une raison qui m’échappe, ils se baladent avec des tas d’objets de valeur comme des marteaux de guerre ou des arcs composites."},{"a":"leather","t":"Et les peaux, cap ? Je peux garder les peaux ?"},{"a":"polonia","t":"Apprends donc à vivre, moussaillon ! Les pirates sont des pillards, pas des assassins !"},{"a":"leather","t":"Oh. Quel gâchis."},{"a":"polonia","t":"Pas du tout. Si on laisse la victime en vie, elle peut refaire le plein de butin qu’on pourra lui re-voler plus tard. Principe économique de base !"},{"a":"polonia","t":"Et maintenant essaie de suivre le rythme si tu veux ta part du butin !"},{"a":"leather","t":"À vos ordres, cap."}]},{"id":"polonia_05","i":5,"title":"Baptême de l’eau","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"carpenter","t":"Voilà le chef-d’œuvre de toute une vie !"},{"a":"polonia","t":"Il... Il est magnifique. Tu arraches une larme à une vieille louve de mer."},{"a":"carpenter","t":"N’est-ce pas ? J’ai dû abandonner certains détails, par exemple cette étrange lubie des canons accrochés au nid-de-pie."},{"a":"carpenter","t":"Mais je crois que le résultat est plus qu’honorable, non ?"},{"a":"polonia","t":"Oh, il l’est, moussaillon. Tiens, voilà tes doublons. Tu les as mérités."},{"a":"carpenter","t":"Absolument ! Oh, une dernière chose, cependant. Le bois n’a pas de secret pour moi, mais tout ce qui est toile et étoffe me dépasse complètement."},{"a":"carpenter","t":"Et sans voile... votre navire n’est pas près de larguer les amarres !"},{"a":"polonia","t":"Ne t’en fais pas, matelot, tu as fait ton travail. Et une voile, j’en ai une."},{"a":"carpenter","t":"Ouah ! Quelle œuvre d’art ! Et magique, en plus ! Où est-ce que vous avez déniché ça ?"},{"a":"polonia","t":"Elle me vient de mon papy Baross. C’était la voile de son navire, le Bonaventure !"},{"a":"carpenter","t":"Je vois. Elle fera une merveilleuse touche finale pour ce fier vaisseau."},{"a":"carpenter","t":"Alors, capitaine Polonia, le Splendide Allan est maintenant à vous !"},{"a":"polonia","t":"Tu l’as appelé le Splendide Allan ?! Et attends une seconde..."},{"a":"polonia","t":"La figure de proue... C’est toi ?! Et à poil ?!"},{"a":"carpenter","t":"Ha ha ha ! Je ne vois pas plus belle figure pour un navire aussi parfait !"}]},{"id":"polonia_b","i":5,"title":"Un pied en avant","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"polonia","t":"Ohé, toi."},{"a":"wood","t":"Ouais ?"},{"a":"polonia","t":"Tranche-moi la jambe."},{"a":"wood","t":"D’accord."},{"a":"polonia","t":"J’AI DIT... Euh, tu es d’accord ?"},{"a":"wood","t":"Ben oui. Étendez juste la jambe là-dessus, j’ai une vieille hache qui devrait faire l’affaire."},{"a":"polonia","t":"Euuuh, une seconde !"},{"a":"wood","t":"Ça ne va pas être beau à voir, mais vous êtes du genre coriace, non ?"},{"a":"wood","t":"Faudra juste poser un bon garrot. Faudrait pas que vous vous vidiez de votre sang."},{"a":"polonia","t":"Holà, matelot, on se calme !"},{"a":"polonia","t":"Mon... Mon navire appareille bientôt, faut que j’embarque ! À la prochaine !"},{"a":"wood","t":"Ha ! On ne s’ennuie jamais, avec les humains."}]},{"id":"polonia_06","i":6,"title":"L’héritage des mers","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Sire, je vous apporte de terribles nouvelles."},{"a":"king","t":"Oh, non ! Ne me dites pas qu’il n’y a plus d’or dans la mystérieuse cité ?"},{"a":"sia","t":"Pas si terrible que ça, heureusement."},{"a":"sia","t":"Mais je crains qu’un affreux pirate ne fasse des siennes à piller votre flotte marchande personnelle."},{"a":"sia","t":"Le montant dérobé est estimé à plus de cent mille milliards de pièces d’or."},{"a":"king","t":"Par la déesse ! Mais, et nos systèmes de détection des pirates ultra perfectionnés ?"},{"a":"sia","t":"Ils n’ont aucun effet, à ce qu’il semble. Comme le grand Baross à l’époque, ce vaisseau échappe à notre magie même la plus puissante."},{"a":"sia","t":"Ainsi, il peut piller vos trésors avant de s’évanouir dans les mers."},{"a":"king","t":"C’est tout bonnement abominable ! Et les équipages ?"},{"a":"sia","t":"Ils sont épargnés tant qu’ils ne résistent pas, sire."},{"a":"king","t":"Ouf. Un peu d’or n’est pas bien cher payé, alors. Je peux manger comme un pauvre jusqu’à ce que ma fortune soit reconstituée !"},{"a":"king","t":"Combien de temps faudra-t-il ?"},{"a":"sia","t":"Environ deux jours, sire."},{"a":"king","t":"Ouille. Les temps sont durs..."}]},{"id":"polonia_07","i":7,"title":"Arrêt au port","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho ! Le capitaine Polonia est au port ! La première tournée est pour moi !"},{"a":"tavern","t":"Polonia ! Ou je devrais plutôt dire, capitaine Polonia ! Alors les affaires tournent bien, hein ?"},{"a":"polonia","t":"Aussi vrai qu’il pleut du rhum au Paradis ! Les mers ne demandent qu’à être écumées !"},{"a":"polonia","t":"Partout où va mon vaisseau, la voile de mon grand-père attrape le vent comme je n’avais encore jamais vu."},{"a":"tavern","t":"Baross serait fier d’apprendre ça, à n’en pas douter. Et ces biens... mal acquis, ils sont destinés à quoi ?"},{"a":"polonia","t":"Moi et mon équipage, on a tout enterré ici et là, comme l’aurait fait n’importe quel vrai pirate."},{"a":"tavern","t":"Ooooh, des cartes au trésor ! Comme c’est palpitant !"},{"a":"polonia","t":"Eh ouais, c’est ça la vie de pirate. Il faut toujours en mettre un peu de côté pour ses vieux jours, comme font les écureuils à terre."},{"a":"tavern","t":"Et le reste ?"},{"a":"polonia","t":"J’ai tout donné à la jolie donzelle du temple."},{"a":"tavern","t":"Un don à l’orphelinat ? Je ne vous voyais pas en âme charitable."},{"a":"polonia","t":"Orphe-qui-quoi ?"},{"a":"tavern","t":"Non, rien. Alors, qu’est-ce que ce sera, capitaine ?"},{"a":"polonia","t":"Ma boisson préférée, du remontant de vieux loup de mer ! Et si y a un marin d’eau douce qui pense avoir l’estomac pour..."},{"a":"polonia","t":"La tournée est pour moi ! La famille Baross a repris du service, yo ho ho !"}]},{"id":"polonia_08","i":8,"title":"Murmures du passé","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Paré pour ta prochaine plongée, triton ?"},{"a":"baker","t":"Quand vous voulez, capitaine ! Mais je dois dire..."},{"a":"baker","t":"J'ai beau être toujours content d'aider à l'exploration sous-marine, je n'ai jamais signé pour être pirate !"},{"a":"polonia","t":"Te triture pas la cervelle, matelot. On fait de la cartographie. Ta capitaine agrandit son territoire."},{"a":"polonia","t":"Pas de piraterie aujourd'hui. Mais si on a de la chance, on pourrait trouver une épave à piller ! Yo ho ho !"},{"a":"baker","t":"Hum, capitaine ? C'est quoi ce vaisseau à l'horizon ?"},{"a":"polonia","t":"Arr. Inutile de frétiller, triton. C'est le Bonaventure ! Le navire de mon papi."},{"a":"baker","t":"Vraiment ? Il semble en triste état..."},{"a":"polonia","t":"...Par la barbe de Neptune ! Ce maudit Bonaventure ! M-mais c'est impossible, papi a passé le sabre à gauche depuis longtemps !"},{"a":"polonia","t":"Matelots ! Changement de plan ! ON SUIT CE NAVIRE !"}]},{"id":"polonia_09","i":9,"title":"Une légende à la dérive","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"baker","t":"...Je n'aurais jamais cru aborder une épave flottante de toute ma vie."},{"a":"polonia","t":"Attention où tu mets les pieds, triton. Ce vaisseau est dans un état lamentable."},{"a":"baker","t":"Franchement, je préfèrerais de beaucoup aller nager ! Et puis, que faisons-nous sur ce navire ?"},{"a":"polonia","t":"Qu'entends-tu par là ? C'est le Baross Bonaventure !"},{"a":"polonia","t":"Je dois découvrir ce qui s'est passé ici... Cette épave ne devrait pas voguer..."},{"a":"baker","t":"...C'est plus un vaisseau fantôme."},{"a":"polonia","t":"Argh, va pas me faire peur comme ça ! Les fantômes n'existent pas !"},{"a":"baker","t":"Et Zo..."},{"a":"polonia","t":"Ferme ton clapet, matelot. Je cherche des indices."},{"a":"baker","t":"Ce journal là-bas semble un peu étrange..."},{"a":"polonia","t":"Arr, le journal du capitaine !"},{"a":"baker","t":"On dirait qu'il vous fixe... pas vrai ?"},{"a":"polonia","t":"Tu viens avec moi, journal. Garde tes yeux de pirate ouverts, au cas où."},{"a":"polonia","t":"...Matelot, arrête de toucher mes cheveux !"},{"a":"baker","t":"Capitaine, je suis là-bas."},{"a":"polonia","t":"...AAAAAARGH !!! Abandonnez le navire !"}]},{"id":"polonia_10","i":10,"title":"Héritage de pirate","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Vot' capitaine est de retour à bord, cher équipage. Hissez les voiles, nous partons."},{"a":"baker","t":"Capitaine, regardez ! Le Bonaventure coule !"},{"a":"polonia","t":"Bernicles ! Comment est-ce possible ? Après tout ce temps ? C'est le journal qui le maintenait à flot ?"},{"a":"baker","t":"...Il a peut-être rempli son objectif."},{"a":"polonia","t":"Baross, espèce de chien de mer... comment aurais-tu pu savoir... ?"},{"a":"baker","t":"Polonia, et le journal ?"},{"a":"polonia","t":"Tu as raison, voyons un peu..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"...J'ai une autre faveur à te demander, triton."},{"a":"baker","t":"Ah oui, laisse-moi te lire ceci."},{"a":"baker","t":"Hum... on dirait des instructions pour trouver un lieu sous l'eau."},{"a":"polonia","t":"Un temple immergé ? On est déjà au courant."},{"a":"baker","t":"Non, ça semble beaucoup plus loin d'ici... Quelque chose à propos de la mystérieuse cité d’or ?"},{"a":"baker","t":"Mais la mystérieuse cité d’or n'est pas sous l'eau..."},{"a":"polonia","t":"Tu veux dire que ce n'était pas une légende ? Cet endroit existe ?"},{"a":"polonia","t":"Triton, tu peux nager. C'est le destin."},{"a":"polonia","t":"Si l'histoire est vraie... tu ne regretteras pas de m'y avoir amenée."}]},{"id":"polonia_11","i":11,"title":"La cité d’or engloutie","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"baker","t":"Pfiou ! Nous y voilà ! Vous tenez le coup, capitaine ?"},{"a":"polonia","t":"*Koff koff* *Ack*..."},{"a":"polonia","t":"Ahhhh... tu as... des jambes sacrément musclées... pour un triton..."},{"a":"baker","t":"Et j'en suis ravi ! Cette entrée est si profond sous la surface, je ne crois pas qu'un humain pourrait l'atteindre."},{"a":"polonia","t":"T'as raison ! Je me suis presque noyée. Je reviendrai jamais ici..."},{"a":"baker","t":"Par la déesse... Polonia, regarde !"},{"a":"polonia","t":"Par la barbe des bernicles... La cité d’or engloutie..."},{"a":"polonia","t":"Cet endroit... Je n’ai jamais rien vu de tel..."},{"a":"baker","t":"Elle déborde de trésors ! De l'or, des perles... La mystérieuse cité d’or semble minable à côté !"},{"a":"polonia","t":"Mon grand-père a cherché cet endroit toute sa vie..."},{"a":"baker","t":"Finalement, il n'a rien pu rapporter à terre, donc il a tout laissé à sa petite-fille préférée."},{"a":"polonia","t":"Sniff... J'en ai la larme à l'œil..."},{"a":"baker","t":"Vous avez besoin de rester seule un moment, capitaine ?"},{"a":"polonia","t":"Tu veux rire ? On a du butin à piller ! Et tu viens de passer capitaine en second. Prêt pour quelques plongées ?"},{"a":"baker","t":"Je dois transporter des sacs de butin ET une pirate ? J'ai intérêt à m'échauffer !"}]},{"id":"polonia_epilogue","i":12,"title":"Épilogue","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Hum..."},{"a":"baker","t":"On se prépare pour une autre plongée, Polonia ?"},{"a":"polonia","t":"Non, matelot. J'ai un gros problème."},{"a":"polonia","t":"J'ai trop d'argent ! Je suis presque à court de plages où l'enterrer."},{"a":"baker","t":"Je dois avouer que je suis aussi un peu submergé par ma part !"},{"a":"baker","t":"Oh, ça me rappelle !"},{"a":"baker","t":"Plus tôt, je suis allé nager autour du Bonaventure coulé..."},{"a":"baker","t":"Il n'y avait pas grand-chose d'intéressant, mais j'ai trouvé ce cache-œil. Vous le reconnaissez ?"},{"a":"polonia","t":"Second ! C'est le cache-œil de Baross !"},{"a":"polonia","t":"Yo ho ho ! Je suis si contente, je pourrais t'embrasser !"},{"a":"baker","t":"Avec plaisir, capitaine. Je suis certain que c'est ce qu'il aurait voulu."},{"a":"polonia","t":"...Tu sais quoi, j'en ai fini avec cette histoire de butins sous-marins."},{"a":"polonia","t":"Le foyer du pirate c'est la mer, pas une cité d'or ! Quel que soit le butin qu'elle renferme."},{"a":"polonia","t":"En tant que petite-fille du grand Baross, je te donne la cité d'or engloutie et tout le butin qui y est encore."},{"a":"polonia","t":"Merci pour ton engagement, second. Si jamais tu changes d'avis à propos de la piraterie, tu seras toujours le bienvenu."},{"a":"baker","t":"Merci, capitaine. Je n'oublierai jamais nos aventures !"},{"a":"baker","t":"...Je suppose qu'il faudra que j'aie une conversation avec Tutu Mano à propos de ces vacances, une fois rentrée !"}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Roi Reinhold..."},{"a":"king","t":"Ah... De toute évidence, mes devoirs me rattrapent !"},{"a":"sia","t":"« S’entassent », plutôt. Les dignitaires attendent."},{"a":"king","t":"Au revoir ! Je reviendrai !"},{"a":"sia","t":"Je ne crois pas, non."}]},{"id":"king_01","i":1,"title":"La cour royale","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"king","t":"La cour royale est ouverte ! Doléants, approchez !"},{"a":"rudo","t":"Humpf."},{"a":"king","t":"Que peut faire le royaume de Reinhold pour ses sujets, imposant... homme-ours ?"},{"a":"rudo","t":"Je crois que vous devriez bannir la magie sous toutes ses formes, et les magiciens avec."},{"a":"king","t":"Ah... c’est... euh..."},{"a":"king","t":"Nous... ferons cas de votre proposition ! Au suivant !"},{"a":"herbs","t":"Saaalut ! Je trouve qu’il faudrait fêter tous les jours la JOURNÉE DE LA PIÑATA !"},{"a":"king","t":"Quelle excellente idée ! Nous pourrions même..."},{"a":"sia","t":"..."},{"a":"king","t":"... passer de longues heures à en débattre. Merci de votre venue !"},{"a":"king","t":"... Sia, combien d’audiences encore aujourd’hui ?"},{"a":"sia","t":"Cinquante-cinq, sire."},{"a":"king","t":"Misère."}]},{"id":"king_02","i":2,"title":"Cœur d’or et tête de linotte","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"donovan","t":"Pardon, cette place est prise ?"},{"a":"sia","t":"Vous venez m’empoisonner la journée, Donovan ?"},{"a":"donovan","t":"Vous me blessez, Sia. Je ne fais qu’interagir avec une concitoyenne impériale."},{"a":"donovan","t":"Comment se porte notre benêt de roi ces temps-ci ?"},{"a":"sia","t":"Votre espionnage est rouillé, Donovan. Reinhold est loin d’être aussi sot que vous le croyez."},{"a":"sia","t":"Derrière son sourire, il consent à bien des sacrifices pour ses sujets."},{"a":"sia","t":"L’empereur... NOTRE empereur aurait d’ailleurs tout intérêt à s’en inspirer."},{"a":"sia","t":"Mon rôle jusqu’ici se résume à l’empêcher de se ruiner au nom de ses sujets."},{"a":"donovan","t":"Tiens donc ? Fascinant."},{"a":"sia","t":"C’est une tête de linotte au cœur d’or, oui. Mais sous-estimez-le à vos risques et périls."}]},{"id":"king_03","i":3,"title":"Royales heures sup’","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"king","t":"Ouf ! Ce tas de rapports n’en finit pas, hein ?"},{"a":"sia","t":"Visiblement, nous sommes bons pour une autre nuit blanche."},{"a":"king","t":"Merci de votre concours, ma chère Sia."},{"a":"sia","t":"Ce n’est rien, sire. Bien, passons au rapport suivant..."},{"a":"sia","t":"Les fermiers de Sudbourg n’ont pas payé la totalité de leurs impôts, la faute selon eux à de mauvaises récoltes."},{"a":"sia","t":"Je crois que c’est la deuxième fois..."},{"a":"king","t":"Envoyez des sorciers de ma cour mener l’enquête. Leurs terres sont peut-être viciées."},{"a":"sia","t":"Une solution très généreuse."},{"a":"king","t":"Et tirez encore un trait sur leurs impôts. C’est ce que mon père aurait voulu !"},{"a":"sia","t":"Fort bien. Je crois en effet que le roi Keinan aurait fait de même."},{"a":"king","t":"Comme elle est lourde, la couronne qu’il a laissée..."},{"a":"king","t":"Que dit le rapport suivant ?"},{"a":"sia","t":"Il parle de tensions frontalières avec l’empire voisin..."}]},{"id":"king_04","i":4,"title":"Frayeurs dans l’ombre","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Sire..."},{"a":"king","t":"Hiii !"},{"a":"king","t":"De grâce, annoncez-vous, si vous comptez surgir dans mon dos !"},{"a":"sia","t":"Ah, vous avez encore cette attaque de ninja à l’esprit, n’est-ce pas ?"},{"a":"king","t":"Évidemment ! J’ai bien failli y rester !"},{"a":"sia","t":"Voulez-vous que je double la garde ?"},{"a":"king","t":"Ce... ne sera pas nécessaire. Mais évitez de marcher si discrètement à l’avenir !"},{"a":"sia","t":"Comme vous le souhaitez, sire."},{"a":"hemma","t":"Ah, ça fait du bien d’être chez soi... Tiens ?"},{"a":"king","t":"AAAH ! Des ninjas ?"},{"a":"hemma","t":"Veuillez nous excuser. Nous avons visiblement dévié."},{"a":"hemma","t":"La Translocation des Ombres est parfois imprécise."},{"a":"king","t":"V-Veuillez vous abstenir d’effectuer la TÉLÉPORTATION DES OMBRES dans ma salle du trône !"},{"a":"sia","t":"R-Roi Reinhold ? Vous allez bien ?"},{"a":"king","t":"Oui ! Montrez donc la sortie à cette... sinistre personne."},{"a":"sia","t":"Fort bien. Je veillerai à ce que le château soit protégé contre ce genre d’intrusions à l’avenir."},{"a":"hemma","t":"Que voilà une halte distrayante. Nous ne manquerons pas de revenir."},{"a":"king","t":"J’espère bien que non !"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"La montagne qui marche","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"Brrr... Je ne suis pas habillé pour ce genre de froid. Qu’est-ce qu’on vient faire là, déjà ?"},{"a":"lilu","t":"Les gemmes qu’on trouve ici on des propriétés extraordinaires ! Grimar m’a dit que..."},{"a":"argon","t":"Attends, Lilu, regarde là-bas ! Il y a un homme qui se bat contre un yéti !"},{"a":"lilu","t":"Un homme ?! C’est une vraie montagne !"},{"a":"lilu","t":"Et attends, on dirait que... il fait une prise de catch au yéti ?!"},{"a":"rudo","t":"Pfiouh... et voilà le dixième."},{"a":"argon","t":"Quel combat, monsieur ! Vous m’avez impressionné !"},{"a":"rudo","t":"Hein ?"},{"a":"lilu","t":"Oh, mais... Vous êtes blessé ! Je vais vous soigner."},{"a":"lilu","t":"<c1>Abrac</c1>..."},{"a":"rudo","t":"ME TOUCHEZ PAS !"},{"a":"rudo","t":"Ça va. Ça va cicatriser tout seul."},{"a":"rudo","t":"Des gamins ont rien à faire dans un endroit pareil. Rentrez chez vous."},{"a":"argon","t":"Ouah, il déteste vraiment la magie, hein ?"},{"a":"lilu","t":"Non. Ce que j’ai vu dans ses yeux, c’était plus de la peur."}]},{"id":"rudo_02","i":2,"title":"Avis d’expulsion","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"elderowen","t":"J’ai peur de ne pas bien comprendre..."},{"a":"rudo","t":"Pfff ! Alors je vais mettre ça en termes simples pour vos vieilles oreilles ramollies."},{"a":"rudo","t":"Le sorcier de la cité est complètement détraqué et devrait être expulsé pour la sécurité de tous."},{"a":"elderowen","t":"Oh, quelles dures paroles."},{"a":"rudo","t":"Pas plus tard qu’hier, il m’a dit de garder Timotheus à l’oeil..."},{"a":"rudo","t":"Il m’a dit que ce « Tim » est perdu dans ses délires et doit absolument être surveillé."},{"a":"rudo","t":"C’est LUI, Timotheus !"},{"a":"elderowen","t":"Hum. Oui, je vois."},{"a":"elderowen","t":"Malgré ses... petits soucis, Timotheus Grimar est un membre estimé de notre cité."},{"a":"elderowen","t":"Il est aussi serviable qu’inoffensif. Je ne vois pas de raison de s’inquiéter."},{"a":"lilu","t":"C’est quoi, ces histoires d’expulser maître Grimar ?!"},{"a":"rudo","t":"Ne te mêle pas de ça, petite."},{"a":"lilu","t":"Si ! Grimar est un puissant sorcier, mais il ne ferait jamais de mal à qui que ce soit !"},{"a":"rudo","t":"Pfff ! Très bien ! Mais si toute la ville explose, ne venez pas dire que je ne vous avais pas prévenus !"},{"a":"elderowen","t":"Il est bien agité, ce jeune homme."},{"a":"lilu","t":"Je ferais bien de le garder à l’œil."}]},{"id":"rudo_03","i":3,"title":"Enfants de l’Étincelle","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"priest","t":"Excusez-moi... Qu’est-ce qui vous tracasse comme ça ?"},{"a":"rudo","t":"Rah, bon sang ! Mais pourquoi est-ce qu’il y a autant de magiciens dans cette cité..."},{"a":"priest","t":"Ah. Monsieur Rudo, j’imagine."},{"a":"rudo","t":"Épargne-moi tes politesses, sorcière."},{"a":"priest","t":"Je suis prêtresse de la déesse, mes pouvoirs sont différents de ceux des sorciers."},{"a":"priest","t":"J’ai fait le serment de consacrer ma vie à la guérison et à la protection."},{"a":"rudo","t":"Je n’y crois pas. Vous les enfants de l’Étincelle, vous êtes tous les mêmes."},{"a":"priest","t":"Vous connaissez l’existence de l’Étincelle ?"},{"a":"rudo","t":"Humpf. Oublie ça. Je m’en vais."},{"a":"priest","t":"Tu nous écoutais, Lilu ?"},{"a":"lilu","t":"Oui, j’ai tout entendu !"},{"a":"priest","t":"Tu te souviens de mes leçons à propos de l’Étincelle ?"},{"a":"lilu","t":"Bien sûr ! Seuls les gens nés avec peuvent manier la magie et créer des sorts."},{"a":"lilu","t":"Mais en général, les gens ordinaires ne savent rien de tout ça."},{"a":"priest","t":"Exactement ! Je n’en attendais pas moins de ma meilleure élève !"},{"a":"priest","t":"Il se pose donc une question... Comment est-il au courant, lui ?"},{"a":"lilu","t":"Hum. Vous pensez que ce pourrait être... ?"}]},{"id":"rudo_04","i":4,"title":"Casse du siècle","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho ! Le capitaine Polonia a tiré le gros lot, cette fois !"},{"a":"polonia","t":"Un caveau royal entier, il n’y a plus qu’à se baisser pour le piller !"},{"a":"rudo","t":"Moins fort, la gondolière. Je suis occupé."},{"a":"polonia","t":"Ça aurait fait un beau butin... Si un butor de berserker n’avait pas TOUT MIS EN PIÈCES !"},{"a":"polonia","t":"Nom d’un sabre en bois, mais qu’est-ce qui t’a pris, moussaillon ?Il y en avait pour trois tonnes de doublons !"},{"a":"rudo","t":"Tout ça, c’est antique."},{"a":"rudo","t":"C’est magique."},{"a":"rudo","t":"Et c’est probablement maudit."},{"a":"rudo","t":"Alors je réduis tout en poussière pour qu’on n’ait pas à attendre que quelqu’un d’autre veuille bien s’en occuper."},{"a":"rudo","t":"Si les habitants de la cité sont trop bouchés pour comprendre le problème, je vais le régler moi-même !"},{"a":"polonia","t":"Holà, moussaillon. Il a l’air de coûter vraiment cher, ce bâton. Tu ne vas quand même pas..."},{"a":"rudo","t":"Humpf."},{"a":"rudo","t":"... Aïe."},{"a":"polonia","t":"Que le grand kraken me croque, mais ne le casse pas comme ça sur ton genou !"},{"a":"polonia","t":"Enfin, on dirait que ce n’est pas le bâton qui a cassé. Il n’a même pas une éraflure."},{"a":"polonia","t":"Dans quel état est ta jambe ?"},{"a":"rudo","t":"Ça ira. Mais il est plus solide qu’il n’en a l’air, ce bâton."},{"a":"rudo","t":"Et c’est bizarre, je n’arrive pas à le lâcher. C’est comme si... comme si il était rivé à ma main."},{"a":"polonia","t":"C’est pas moi le médecin de bord, mais on dirait bien que tu t’es collé une petite malédiction."},{"a":"polonia","t":"Tu devrais peut-être aller consulter."},{"a":"rudo","t":"Évidemment, il fallait que ce soit une magie maudite. C’est TOUJOURS une magie maudite."},{"a":"rudo","t":"Pfff. Je me tire. Casse donc le reste pour moi."},{"a":"polonia","t":"Tu l’as dit, moussaillon !"},{"a":"polonia","t":"Ouais, enfin... C’est surtout la baraque que je vais casser. En avant pour le pillage !"}]},{"id":"rudo_a","i":4,"title":"Amour vache","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"herbs","t":"Gorza !"},{"a":"gems","t":"Gorza ! <sprite tint=1 name=Note2>"},{"a":"wood","t":"Salut, Genièvre. Oh, et Maylee ! Qu’est-ce qui vous amène ?"},{"a":"herbs","t":"On discutait de son futur prince charmant..."},{"a":"gems","t":"Houuu, j’ai tellement hâte !"},{"a":"herbs","t":"Et on se demandait... Comment tu as rencontré le tien ?"},{"a":"wood","t":"Ce gros balourd de Rudo ? Ha !"},{"a":"wood","t":"Il n’a peut-être pas l’air comme ça, mais il sait vraiment parler aux femmes."},{"a":"wood","t":"Voyons que je me rappelle. Voilà comment ça s’est passé..."},{"a":"rudo","t":"Et encore un petit pour la route."},{"a":"tavern","t":"Dites-moi, Rudo... Vous avez déjà réfléchi à vous fixer quelque part ?"},{"a":"rudo","t":"Occupe-toi de tes affaires, Naya. J’ai pas le temps pour ces salades."},{"a":"tavern","t":"L’amour surgit toujours au moment où on s’y attend le moins ! Qui sait, la femme de vos rêves pourrait passer la porte d’une seconde à l’autre..."},{"a":"rudo","t":"Pah ! Déjà, il faudra une femme qui soit capable de me plaquer au sol."},{"a":"wood","t":"C’est un défi que tu me lances, mon grand ?"},{"a":"rudo","t":"Essaie un peu, je vais te casser les dents !"},{"a":"tavern","t":"Gorza, reposez cette chaise, s’il vous plaît."},{"a":"wood","t":"Alors, tête de lard. Tu en veux encore ?"},{"a":"rudo","t":"RAAAARRH !!!"},{"a":"wood","t":"Ouah !"},{"a":"wood","t":"Et une semaine plus tard, on s’est mariés. J’avais jamais vu autant de blessés à un mariage."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"Hum, on va peut-être aller demander à quelqu’un d’autre."}]},{"id":"rudo_05","i":5,"title":"Malédictions et imprécations","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"rudo","t":"Comment ça, incassable ?!"},{"a":"master","t":"C’est comme ça, mon brutal ami. Cette relique est incassable."},{"a":"rudo","t":"Et à quoi ça sert d’avoir un marteau en adamantium s’il ne peut pas casser un pauvre petit bâton !"},{"a":"master","t":"Ça ne peut pas être aussi faible... Ça m'a l'air très maléfique !"},{"a":"master","t":"Quoi qu’il en soit, il y a aussi autre chose. Sans doute de la magie..."},{"a":"rudo","t":"Mais ÉVIDEMMENT que c’est de la magie."},{"a":"rudo","t":"C’est toujours de la satanée magie."},{"a":"master","t":"On dirait que je ne t’apprends rien, alors. Pourquoi ne vas-tu pas trouver quelqu’un qui s’y connaît en ce domaine, plutôt ?"},{"a":"rudo","t":"Impossible de faire confiance aux mages... Absolument pas."},{"a":"master","t":"Et pourtant on dirait que là, tu ne vas pas avoir le choix."},{"a":"master","t":"Et puis, qui ne ferait pas confiance à la petite Lilu ? Elle est adorable !"},{"a":"rudo","t":"C’est une mage. Elle est comme les autres, c’est tout."},{"a":"rudo","t":"Dangereuse. Sournoise. Malfaisante."},{"a":"master","t":"En tout cas elle est sans doute la seule qui pourra t’aider si tu veux être débarrassé de ce bâton un jour."},{"a":"rudo","t":"Bon sang."}]},{"id":"rudo_06","i":6,"title":"Sorcier malgré lui","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"rudo","t":"Salut Naya, comme d'hab."},{"a":"tavern","t":"Désolée Rudo, pas d'armes à l'intérieur. Tu connais la règle."},{"a":"rudo","t":"Ça ? C'est une canne."},{"a":"tavern","t":"Je ne crois pas ! Je sais reconnaître un bâton magique quand j'en vois un !"},{"a":"rudo","t":"Peuh. Bon. Tu vois ça ? On ne fait pas plus maudit. Je ne peux pas le retirer."},{"a":"tavern","t":"Mince ! Dans ce cas, je suppose qu'on peut faire une petite exception. Rien que pour toi !"},{"a":"rudo","t":"Humpf. Merci."},{"a":"tavern","t":"Alors, qu’est-ce que tu vas faire ?"},{"a":"rudo","t":"Ignore ça. Je vais juste vivre avec."},{"a":"tavern","t":"Vraiment ? Je dirais qu'il te rend grognon. Enfin, plus grognon que d'habitude, si c'est vraiment possible."},{"a":"tavern","t":"Et puis, à te voir, tout le monde va penser que tu es une sorte de mage."},{"a":"rudo","t":"Vraiment ? Un mage maudit ?"},{"a":"tavern","t":"Il ne te manque qu'un chapeau ridicule ! Et une meilleure attitude !"},{"a":"rudo","t":"Tu as peut-être raison. Je dois y remédier. À plus."},{"a":"tavern","t":"Bonne journée. Je rajoute ça sur ton ardoise !"}]},{"id":"rudo_07","i":7,"title":"Aperçu de traumatisme","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"rudo","t":"Désolé pour avant. On m'a dit que tu pourrais... m'aider avec cette malédiction."},{"a":"lilu","t":"Ce bâton, hein ? Il a l'air vraiment mauvais !"},{"a":"lilu","t":"Je n'ai jamais tenté de neutraliser une malédiction avant, mais en théorie... je devrais pouvoir y arriver."},{"a":"lilu","t":"Tu es vraiment prêt pour ça ? Tu as l'air très nerveux."},{"a":"rudo","t":"Oui."},{"a":"lilu","t":"D'accord ! Laisse-moi d'abord me concentrer..."},{"a":"lilu","t":"Je vois la malédiction... qui t'enveloppe en entier."},{"a":"lilu","t":"Ne bouge pas, je dois approfondir..."},{"a":"rudo","t":"...Nghn !"},{"a":"lilu","t":"Ouah !"},{"a":"lilu","t":"On dirait vraiment, mais VRAIMENT, que tu étais sur le point de me cogner !"},{"a":"rudo","t":"Désolé. Ça n'était pas voulu."},{"a":"lilu","t":"Je ne crois pas que ça va marcher. J'ai besoin de me concentrer, tu comprends ?"},{"a":"rudo","t":"Ouais, c'est ma faute. Je vais trouver une autre solution."},{"a":"lilu","t":"Pourquoi ne pas demander à Maladie ? Elle remarquera peut-être quelque chose que je n'ai pas vu."},{"a":"rudo","t":"Maladie, hein ? Je vais essayer."},{"a":"lilu","t":"Mais sois gentil ! Elle a des... spécificités dont tu devrais être au courant..."}]},{"id":"rudo_08","i":8,"title":"Assez de malédiction pour deux","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"rudo","t":"Mademoiselle Maladie, vous avez un moment ?"},{"a":"malady","t":"(Oh non, Lilu m'avait avertie à son propos...)"},{"a":"malady","t":"Hum... désolé. Je ne crois pas..."},{"a":"rudo","t":"Désolé, je voulais pas vous faire peur. Mais vous savez peut-être quelque chose sur ce bâton."},{"a":"malady","t":"Je... croyais que vous détestiez la magie ?"},{"a":"rudo","t":"Plus que tout au monde."},{"a":"rudo","t":"Mais vous êtes maudite, pas vrai ? Comme moi."},{"a":"rudo","t":"Vous avez pas choisi la magie. C'est pas de votre faute."},{"a":"malady","t":"...Dans ce cas, je peux essayer de... parler au bâton."},{"a":"malady","t":"..."},{"a":"malady","t":"...Il a l'air d'un parasite. Il se nourrit de votre Étincelle."},{"a":"rudo","t":"Cette chose est intelligente ?"},{"a":"malady","t":"Oui... d'une certaine façon."},{"a":"malady","t":"Votre Étincelle a l'air très puissante. Cela pourrait prendre des décennies, mais..."},{"a":"malady","t":"...Il peut peut-être vous libérer de votre magie... ?"},{"a":"rudo","t":"Pfff. Je ne compterais pas là-dessus."},{"a":"rudo","t":"Alors il veut juste aspirer de la magie, hein ?"},{"a":"malady","t":"Hum... oui. Plus ou moins."},{"a":"malady","t":"S'il vous plaît... Je suis déjà maudite, alors..."},{"a":"rudo","t":"Hah ! J'oserais sûrement pas, mam’zelle."},{"a":"rudo","t":"Merci pour l’aide. Je crois que j'ai une idée..."}]},{"id":"rudo_09","i":9,"title":"Le passé d'un soldat","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"malady","t":"Hum, je peux entrer ?"},{"a":"veteran","t":"Ah, la Méduse, j'en ai tellement entendu parler."},{"a":"veteran","t":"Approche, petite. Je n'ai pas de chaise à ta taille j'en ai peur."},{"a":"malady","t":"Ce n'est pas grave... merci. Je voulais vous interroger à propos de cet homme, Rudo."},{"a":"veteran","t":"Ce grand benêt ? Il ne t'a pas harcelée, n'est-ce pas ?"},{"a":"malady","t":"Non, il a été... inhabituellement gentil avec moi."},{"a":"veteran","t":"Vraiment ? C'est étrange, il déteste vraiment la magie."},{"a":"malady","t":"C'est pourquoi je suis venue. Je voulais te demander... pourquoi ?"},{"a":"veteran","t":"Nous faisions partie de l'armée de l'Empire avant. De vieux compagnons d'armes."},{"a":"veteran","t":"Rudo a été... désigné volontaire pour participer à une expérience qui visait à implanter artificiellement l'Étincelle chez les soldats."},{"a":"veteran","t":"Ça a été une terrible affaire. Après ça, il n'a plus jamais été le même."},{"a":"malady","t":"C'est horrible... "},{"a":"veteran","t":"Et c'est encore plus horrible que ça en a l'air. Nous avons déguerpi dès que nous avons pu."},{"a":"malady","t":"Est-ce qu'au moins... ça a marché ? J'ai senti une Étincelle extrêmement puissante en lui..."},{"a":"veteran","t":"Difficile à dire. Vous avez vu comme il est. L'empereur en personne ne pourrait lui faire lancer le plus simple des sorts."},{"a":"malady","t":"Et maintenant... à cause de ça, il subit cette terrible malédiction... Comment pouvons-nous l'aider ?"},{"a":"veteran","t":"Il est venu vous voir, pas vrai ? Le fait qu'il demande de l'aide est bon signe ! "},{"a":"veteran","t":"Ce gamin n'est pas le plus malin, mais il est tenace. Je suis sûr qu'il trouvera une solution."}]},{"id":"rudo_10","i":10,"title":"Transfert de propriété","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"rudo","t":"D'accord, espèce de sac d'os. On va passer un marché."},{"a":"rudo","t":"Je vais te livrer à ce troubelin là-bas."},{"a":"monster_Forest_Blacksmith","t":"Aaah ! Lâchez-moi !"},{"a":"rudo","t":"Vous devenez les meilleurs amis du monde et on oublie ce qui s'est passé."},{"a":"rudo","t":"Si tu ne veux pas faire ça..."},{"a":"rudo","t":"Je plonge dans la lave et on voit qui résiste le plus longtemps."},{"a":"rudo","t":"Alors tu choisis quoi ? L'« eau » a l'air bonne, d'après moi !"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"...Bon choix. Amuse-toi bien avec ce troubelin."},{"a":"monster_Forest_Blacksmith","t":"Argh ! C'est... coincé !"},{"a":"rudo","t":"Bouah ha ha ha ! Si long !"}]},{"id":"rudo_epilogue","i":11,"title":"Épilogue","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"lilu","t":"Rudo ! À propos de la dernière fois..."},{"a":"rudo","t":"Hm ?"},{"a":"lilu","t":"Oh ! Tu t'es débarrassé du bâton !"},{"a":"rudo","t":"C'est vrai. Ça fait toujours un souci de moins."},{"a":"rudo","t":"... Pardon pour la fois dernière. J'étais un peu sur les nerfs."},{"a":"lilu","t":"... Je suppose que je peux te pardonner. Mais tu vas devoir travailler ton attitude envers les mages !"},{"a":"rudo","t":"Hah ! C'était inattendu, mais cette Maladie a été utile. Qui sait, je finirai peut-être par changer d'avis."},{"a":"lilu","t":"Elle a réussi à lever la malédiction ?"},{"a":"rudo","t":"Pas exactement. Mais grâce à elle, j'ai trouvé une main secourable... inattendue."},{"a":"rudo","t":"Coopérer un peu de temps en temps ne fait pas de mal. Gah hah !"},{"a":"argon","t":"Ashley, attention ! Il arrive autre chose !"},{"a":"ashley","t":"Je suis prête à tout ! Viens par ici, animal !"},{"a":"monster_Forest_Blacksmith","t":"... À l'aide..."},{"a":"argon","t":"Hein ?"},{"a":"ashley","t":"Heiiiin ?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Premiers pas royaux","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"king","t":"Sia, ma décision est prise !"},{"a":"sia","t":"Oui, sire ?"},{"a":"king","t":"Aujourd’hui, je veux faire les magasins !"},{"a":"sia","t":"Excellente idée, sire."},{"a":"sia","t":"Cependant, d’après votre emploi du temps, il semble que vous ayiez une rencontre avec des dignitaires étrangers, aujourd’hui..."},{"a":"king","t":"Quelle barbe. On ne peut pas les renvoyer chez eux ?"},{"a":"sia","t":"Sire, n’oubliez pas que malgré votre jeunesse, vous êtes le roi. La loi, c’est vous."},{"a":"king","t":"Mais... c’est indéniable ! Alors ce sera les magasins ! Les dignitaires attendront."},{"a":"sia","t":"Une admirable décision. Dois-je vous accompagner ?"},{"a":"king","t":"Bien sûr ! Je n’ai confiance qu’en vous pour la protection de ma gracieuse personne."}]},{"id":"sia_02","i":2,"title":"Des amis en bas lieu","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"[...] J’ai donc des raisons de croire que la vie du roi peut être en danger."},{"a":"elderowen","t":"Je vois. C’est vrai qu’il y a plusieurs royaumes concurrents qui auraient intérêt à attenter à ses jours."},{"a":"elderowen","t":"Je n’ai remarqué personne de suspect, mais Naya, de la taverne, devrait être mieux renseignée."},{"a":"sia","t":"Merci, Owen. Sagesse et patriotisme, comme toujours."},{"a":"elderowen","t":"Ce n’est rien. C’est mon devoir de citoyen de veiller au bien du royaume."},{"a":"elderowen","t":"Il est encore jeune et naïf, mais je suis sûr que Reinhold fera un excellent roi... avec le temps."},{"a":"sia","t":"Et c’est à moi de m’assurer qu’il reste en vie jusque-là !"},{"a":"tavern","t":"Mais dites donc, ce n’est pas souvent qu’on voit du joli sang bleu à la taverne !"},{"a":"sia","t":"Arrête ta comédie, Naya. Tu sais qui je suis."},{"a":"tavern","t":"Mais oui ! Sia Leonel, mise au service de notre roi par l’empereur de Kern..."},{"a":"tavern","t":"Pour lui servir de conseillère, mais aussi pour le surveiller un peu, hein ?"},{"a":"sia","t":"!!"},{"a":"sia","t":"Tu es une fouineuse, toi, non ?"},{"a":"sia","t":"Alors dis-moi, Naya la fouineuse..."},{"a":"sia","t":"Tu aurais vu des gens bizarres à la taverne, ces temps-ci ?"},{"a":"tavern","t":"Oh, des gens bizarres, on en voit tout le temps. Des orcs éméchés, des marchands débutants..."},{"a":"tavern","t":"Mais la plus étrange de tous, c’est sans doute la fille dans le coin là-bas."},{"a":"yami","t":"!!"},{"a":"sia","t":"Elle s’est échappée..."},{"a":"sia","t":"C’était une espionne azumane ! Une espionne... ou un assassin."},{"a":"sia","t":"Il va falloir redoubler de vigilance."}]},{"id":"sia_03","i":3,"title":"Intrusion","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Si nous sommes réunis ici aujourd'hui, c'est pour célébrer l'incroyable générosité de notre roi."},{"a":"sia","t":"Ces derniers mois, il a donné plusieurs millions de pièces d'or de ses propres coffres..."},{"a":"sia","t":"...À plusieurs temples, écoles et orphelinats du coin."},{"a":"sia","t":"Vous êtes tous les bienvenus à cette fête, alors dites-le à vos amis et à votre famille."},{"a":"sia","t":"Longue vie au roi Reinhold !"},{"a":"yami","t":"Reinhold, espèce de tyran ! Ton règne se termine sans plus tarder !"},{"a":"king","t":"Aaargh..."},{"a":"sia","t":"Un shuriken... ! Cette espionne azumane !"},{"a":"sia","t":"Gardes ! Formez un périmètre autour du château ! Ne laissez personne s'échapper !"},{"a":"sia","t":"Argon, poursuis cet assassin !"},{"a":"argon","t":"Et plus vite que ça !"},{"a":"sia","t":"Toi ! Bouffon malodorant ! Tu ne vois pas que le roi est blessé ! Va chercher un guérisseur et vite !"},{"a":"leather","t":"Waouh, un peu de respect, quand même !"},{"a":"sia","t":"(J'avais fait en sorte que tous les points d'accès soient sous surveillance maximale...)"},{"a":"sia","t":"(...Mais qui est cette fille ?)"}]},{"id":"sia_04","i":4,"title":"Courrier noirci par la fumée","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Bruyante Naya, je crois bien que tu me dois quelques explications."},{"a":"tavern","t":"Oh, madame Leonel... Je crois que c'est VOUS qui me devez des explications."},{"a":"sia","t":"Je vous demande pardon ?"},{"a":"tavern","t":"J'ai intercepté des lettres TRÈS intéressantes. Que vous avez envoyées, de toute évidence."},{"a":"tavern","t":"Et si nous les lisions ensemble ?"},{"a":"sia","t":"... !"},{"a":"tavern","t":"Voyons voir... Un sceau de Kern, envoyé directement à l'empereur de Kern ?"},{"a":"tavern","t":"Eh bien dites donc. J'espérais vraiment une liaison sentimentale scandaleuse, mais j'imagine qu'une affaire de trahison conviendra également."},{"a":"sia","t":"N... Naya, arrête, s'il te plaît !"},{"a":"tavern","t":"Ah ! Voilà un passage très croustillant !"},{"a":"tavern","t":"« Le roi Reinhold est un imbécile fini dont la présence sur le trône t'est grandement bénéfique. »"},{"a":"tavern","t":"« Si ce souverain reste en vie, il causera sûrement davantage de dégâts à son royaume que s'il venait à mourir. »"},{"a":"sia","t":"..."},{"a":"tavern","t":"Je dirais que de tels écrits si négatifs ne sont pas dignes de la conseillère du roi !"},{"a":"sia","t":"Naya... la curieuse... Tu vas me payer ça !"},{"a":"tavern","t":"Un jour, peut-être. Mais pour l'instant, je crois que c'est vous qui allez payer. Et cher, j'imagine."},{"a":"sia","t":"... Tu t'abaisses à faire du chantage ?"},{"a":"tavern","t":"Une faute bien insignifiante en comparaison à la trahison !"},{"a":"tavern","t":"Si vous aviez prévu de faire du mal à notre roi, d'un autre côté..."},{"a":"sia","t":"Mmm. Très bien. Donne ton prix. Et prie pour que ton réseau d'espionnage ne soit jamais plus malin que le tien, Naya."},{"a":"tavern","t":"Je suis impatiente de voir ça !"}]},{"id":"sia_a","i":4,"title":"Un caprice de roi","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Jetons de fortune"},"side":true,"lines":[{"a":"sia","t":"Sire ?"},{"a":"king","t":"Ah, ma chère Sia ! Qu’est-ce que je peux faire pour vous ?"},{"a":"sia","t":"Est-ce que par hasard vous auriez eu l’une de vos frénésies de caprices, ces derniers temps ?"},{"a":"king","t":"Je, euh... Non ! Bien sûr que non, jamais je ne ferais une chose pareille !"},{"a":"sia","t":"Ah. C’est étrange, d’après l’inventaire, la chambre fort nº36 est pleine à craquer de <c1>kunaïs</c1>."},{"a":"sia","t":"Nul besoin de rappeler à sa Majesté qu’il s’agit d’un objet extrêmement rare."},{"a":"king","t":"Je suis sûr qu’il y a une explication parfaitement log..."},{"a":"sia","t":"De plus, un bon nombre des pièces de collection les plus rares du royaume ont mystérieusement échoué entre les mains de gens du peuple."},{"a":"sia","t":"Sire, votre générosité est admirable..."},{"a":"sia","t":"Mais par pitié, retenez-vous de distribuer à qui veut des reliques à la valeur inestimable juste pour financer vos envies pressantes."},{"a":"king","t":"Humpf. Fort bien ! C’est décidé, à partir de dorénavant, je suis un homme nouveau !"},{"a":"sia","t":"Merci pour votre compréhension. À présent, si vous voulez bien m’excuser."},{"a":"king","t":"J’ai une volonté d’acier ! Fi du matérialisme, je n’ai pas besoin de posséder tous ces objets !"},{"a":"king","t":"Hum... Est-ce qu’il ne manquerait pas quelques <c1>lames royales</c1> pour décorer cette pièce ?"}]},{"id":"sia_05","i":5,"title":"L’agent Swan","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"« Par un incroyable coup du sort, quelqu’un a attenté à la vie du roi Reinhold. »"},{"a":"sia","t":"« C’est Azuma qui semble être derrière l’attaque. L’agent Swan va enquêter. »"},{"a":"king","t":"Oh, Sia ! Qu’est-ce que vous faites ?"},{"a":"sia","t":"J’écris juste une petite lettre, n’y prêtez pas attention."},{"a":"sia","t":"(C’est juste mon rapport à l’empereur de Kern...)"},{"a":"king","t":"Parfait ! Il y a des dignitaires étrangers qui m’attendent."},{"a":"king","t":"Ils se pourraient qu’ils soient, euh, un rien offensés par ma décision d’aller faire les magasins la dernière fois."},{"a":"king","t":"J’apprécierais énormément votre aide pour désamorcer cette épineuse situation !"},{"a":"sia","t":"Bien entendu. J’arrive incessamment, sire."},{"a":"sia","t":"Prévenir l’empereur de cette tentative d’assassinat pourrait avoir des conséquences terribles..."},{"a":"sia","t":"Il faut que j’y réfléchisse. Le royaume n’est... n’est pas encore prêt à affronter Kern."},{"a":"sia","t":"Pour le bien de tous, je pourrais peut-être oublier de mentionner ce petit détail."},{"a":"sia","t":"« Tout se passe comme prévu. L’agent Swan n’a rien de particulier à signaler ce mois-ci. »"}]},{"id":"sia_06","i":6,"title":"La rose et l’épine","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"king","t":"Sia ! Vous avez de la visite. Et du genre aristocratique, on dirait bien."},{"a":"sia","t":"Aristocratique, sire ? Non, ça ne peut pas être..."},{"a":"donovan","t":"Dame Sia."},{"a":"sia","t":"... Donovan."},{"a":"sia","t":"Sire, une affaire urgente requiert votre présence au trésor royal. Je vous recommenderais d’intervenir immédiatement."},{"a":"king","t":"Oh, le dernier arrivage d’or pur, peut-être ? J’ai hâte !"},{"a":"donovan","t":"Toujours aussi naïf ce pauvre roi, hein ?"},{"a":"sia","t":"Quel vent mauvais t’amène au royaume de Reinhold, alchimiste ?"},{"a":"donovan","t":"Tu ne mâches toujours pas tes mots à ce que je vois, cher agent Swan."},{"a":"donovan","t":"C’est un simple voyage d’agrément, rien de plus. Avec la permission de l’empereur de Kern, bien entendu."},{"a":"donovan","t":"Je viens sentir les fleurs de la région, goûter aux potions locales... Des vacances d’alchimiste, en somme."},{"a":"sia","t":"Et ici, comme par hasard ?"},{"a":"donovan","t":"Pour tout primitif qu’il soit, ce royaume semble avoir un bon nombre d’alchimistes de talent."},{"a":"donovan","t":"Mais si je venais par hasard à constater un défaut de loyauté d’un certain agent..."},{"a":"sia","t":"Le message est clair, Donovan. Va donc profiter de tes... « vacances »."},{"a":"donovan","t":"Fort bien, dame Sia. C’est toujours un plaisir de te voir."},{"a":"sia","t":"Arh. Voilà une autre épine dans le pied."}]},{"id":"sia_07","i":7,"title":"L’étranger dans la ville d’or","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Donovan ? Désolée de vous interrompre en pleine séance d’espionnage, j’espère que je ne dérange pas."},{"a":"donovan","t":"Oh, dame Sia !"},{"a":"donovan","t":"Mais pas du tout, j’étais juste en train de visiter un peu."},{"a":"sia","t":"Allons, nul besoin de vous cacher. La mystérieuse cité d’or est ouverte à tous."},{"a":"sia","t":"Cependant, n’oubliez pas que les lois du royaume stipulent que tout l’<c1>or pur</c1> trouvé ici est la propriété de sire Reinhold."},{"a":"sia","t":"Et en échange de leur contribution, les valeureux aventuriers sont récompensés."},{"a":"donovan","t":"Je vois. Votre monarque est bien... généreux."},{"a":"donovan","t":"Cet <c1>or pur</c1> est alors frappé en pièces de monnaie, ce qui entraîne une forte inflation..."},{"a":"sia","t":"C’est bien ça. Je vois que vous interceptez assidûment mes courriers à l’empereur."},{"a":"donovan","t":"J’aime me tenir au courant."},{"a":"sia","t":"Bon, puisque vous êtes là, rendez-vous utile. Rapportez donc un chargement d’<c1>or pur</c1> au château."},{"a":"donovan","t":"Bien sûr. Je ne peux rien vous refuser."},{"a":"sia","t":"Et faites attention à ne pas vous casser un ongle, cher Donovan."}]},{"id":"sia_08","i":8,"title":"Au carrefour du destin","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"tavern","t":"Ma petite Swan est de retour ! Toujours aussi ponctuelle, comme il sied à notre meilleure administratrice."},{"a":"sia","t":"J’ai répondu à ton appel, Naya la fouineuse. Abrège, je suis d’humeur massacrante."},{"a":"tavern","t":"Alors le massacre va être total ! J’ai intercepté un courrier d’un certain alchimiste..."},{"a":"tavern","t":"Et en magiposte prioritaire, hein ! Tu n’imagines pas à quel point c’est compliqué à obtenir !"},{"a":"sia","t":"Ne me dis pas que..."},{"a":"tavern","t":"Apparemment, ce Donovan a vu clair dans ton petit jeu."},{"a":"sia","t":"Si tu l’as intercepté, alors..."},{"a":"tavern","t":"Eh oui, il n’ira nulle part ! Si tu allonges la monnaie, bien sûr."},{"a":"sia","t":"Je... Soit. Donne-moi ton prix, Naya. Je vais payer."},{"a":"tavern","t":"J’ai augmenté mes tarifs habituels. Je demande une prime spéciale en dédommagement."},{"a":"sia","t":"Très bien. Je consens..."},{"a":"tavern","t":"Choisis ton camp, Sia. Voilà mon prix."},{"a":"sia","t":"..."},{"a":"tavern","t":"À vouloir jouer sur les deux tableaux, tu as fini par te mettre dans de sales draps."},{"a":"tavern","t":"Bien sûr, en fonction de ta réponse, je pourrai peut-être t’aider..."}]},{"id":"sia_09","i":9,"title":"Chaîne de trahison","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Cher Donovan. Si je peux me permettre, j’ai une demande."},{"a":"donovan","t":"Oh ? Ma foi, j’écoute."},{"a":"sia","t":"Allez annoncer à l’empereur que l’agent Swan est mort. Un trépas tragique et honorable au service de l’empire."},{"a":"donovan","t":"P-pardon ?"},{"a":"sia","t":"Je jette l’éponge, Donovan. Ou plutôt, je change de camp."},{"a":"sia","t":"Et ce sera vous qui l’annoncerez. En donnant du crédit à mon histoire, bien sûr."},{"a":"donovan","t":"R-ridicule ! C’est de la haute trahison ! Jamais je ne..."},{"a":"sia","t":"Au contraire, Donovan. Sauf si vous souhaitez que le monde découvre la recette de votre élixir d’immortalité ?"},{"a":"donovan","t":"À d’autres, Sia. Je n’ai jamais révélé cette recette à quiconque. Il est impossible que..."},{"a":"sia","t":"Qu’est-ce que c’était, déjà ? Les ailes d’un éphémère centenaire... de l’eau du Styx... ?"},{"a":"donovan","t":"C-c’est..."},{"a":"sia","t":"Il y avait quantité d’ingrédients... dont un trait de vin pour le goût, si je ne m’abuse ?"},{"a":"donovan","t":"S-silence ! SILENCE ! J’ignore par quel moyen maléfique vous avez appris ça..."},{"a":"sia","t":"De toute évidence, vous avez sous-estimé mon réseau d’espions."},{"a":"donovan","t":"... Mais j’accepte de me prêter à votre petit jeu. Pour cette fois."},{"a":"sia","t":"Toujours à broyer du noir ? Je trouve pourtant mes conditions plus que généreuses."},{"a":"sia","t":"Que vaut une petite trahison face à l’œuvre d’une vie ?"}]},{"id":"sia_10","i":10,"title":"Aide posthume","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Agent Murmure. C’est moi."},{"a":"essence","t":"*Bâille*... déjà ?"},{"a":"sia","t":"Vos informations étaient justes. Félicitations, excellent travail."},{"a":"essence","t":"Ce... n’est rien..."},{"a":"sia","t":"Donovan a toujours été prudent, mais j’imagine qu’on peut difficilement empêcher un fantôme de nous espionner !"},{"a":"essence","t":"C’est clair..."},{"a":"essence","t":"Il avait l’air... très en rogne..."},{"a":"sia","t":"Comme convenu, je vous verse votre paiement en offrande sur votre tombe."},{"a":"sia","t":"J’ai ajouté un petit extra au passage. Allez encore tourmenter un peu Donovan, pour la peine."},{"a":"essence","t":"On me paie... pour faire des trucs de fantôme. C’est génial."}]},{"id":"sia_11","i":11,"title":"Swan déploie ses ailes","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"king","t":"Sia ! Je tiens à peine sur place ! Combien de temps dois-je encore attendre avant de pouvoir dévoiler au monde mes caprices ?"},{"a":"sia","t":"Ça ne fait que quelques jours, votre Majesté. Veuillez patienter encore un peu."},{"a":"king","t":"Ah ! À quoi donc rime cette paperasse ?"},{"a":"sia","t":"Ce sont des certificats de naissance et autres documents administratifs importants à mon sujet."},{"a":"sia","t":"Par pure coïncidence, la plupart des documents retraçant ma vie dans ce royaume semblent avoir disparu."},{"a":"sia","t":"Je me suis donc attachée à remplir ces formulaires de mémoire."},{"a":"king","t":"Bien sûr ! Pas question que ma meilleure conseillère ne soit pas sujette officielle de mon royaume !"},{"a":"king","t":"Tenez ! Je vais les frapper séance tenante de mon sceau royal !"},{"a":"king","t":"Et voilà ! Aucun détail ne vous échappe, comme toujours !"},{"a":"sia","t":"Merci, votre Majesté. J’espère vous servir bien des décennies encore."},{"a":"king","t":"J’en serais fort aise !"},{"a":"king","t":"Sia, est-ce une larme que j’aperçois ? Le remplissage de formulaires vous est-il donc source de jubilation si intense ?"},{"a":"sia","t":"Ah... non. Disons plutôt que j’en pleure d’ennui."},{"a":"sia","t":"Sur ce ! Et si nous discutions de vos caprices ?"},{"a":"king","t":"Volontiers ! Si vous voulez mon avis, notre approvisionnement en boucliers..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Sokka le grand guerrier","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"atlab_aang","t":"Et que dites-vous de... ceci ?"},{"a":"tavern","t":"Oh, joli !"},{"a":"atlab_sokka","t":"Pfff. Il fait ça à tout bout de champ."},{"a":"argon","t":"Sokka, c’est ça ? Je m’appelle Argon !"},{"a":"atlab_sokka","t":"Salut. Si tu veux voir des tours de maître, parle à Aang."},{"a":"argon","t":"Oh, non. La magie, ou ce que vous appelez maîtrise, je n’y connais pas grand-chose."},{"a":"argon","t":"J’ai vu ton équipement et je me suis dit que tu devais être un redoutable guerrier."},{"a":"atlab_sokka","t":"R-Redoutable ?"},{"a":"atlab_sokka","t":"T-Tout à fait ! Je suis Sokka, le grand guerrier de l’équipe Avatar !"},{"a":"argon","t":"Je le savais ! Tu dois avoir des récits formidables à raconter."},{"a":"atlab_sokka","t":"Tu m’étonnes ! Par exemple, pendant le siège d’Agna Qel’a..."},{"a":"atlab_sokka","t":"Et voilà comment ma petite amie de l’époque est devenue la Lune."},{"a":"argon","t":"La... Lune ?"},{"a":"atlab_sokka","t":"Oui. Mais ensuite, la flotte de la Nation du Feu..."},{"a":"atlab_sokka","t":"... et bim ! J’ai étendu raide la chouette géante dans la bibliothèque."},{"a":"argon","t":"Incroyable ! Pourtant, c’était un puissant esprit, non ?"},{"a":"atlab_sokka","t":"Si ! Mais l’équipe Avatar est toujours victorieuse quand Sokka est de la partie !"},{"a":"atlab_sokka","t":"... À propos, où est Aang ?"},{"a":"argon","t":"Oh, il est parti il y a une heure environ."},{"a":"atlab_sokka","t":"Mince ! J’ai perdu toute notion du temps. Désolé, Argon, il faut que je file !"}]},{"id":"atlab_sokka_02","i":2,"title":"Sokka le grand forgeron","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"blacksmith","t":"Tu travailles dur, Sokka ?"},{"a":"atlab_sokka","t":"Bonjour, Wallace. Merci de m’avoir prêté vos outils !"},{"a":"blacksmith","t":"Pas de problème. Je ne pensais pas que tu serais si doué, à ton âge !"},{"a":"atlab_sokka","t":"Quand on est le seul du groupe qui ne maîtrise aucun élément, il faut bien se trouver d’autres atouts."},{"a":"atlab_sokka","t":"J’ai rarement accès à d’aussi bons outils..."},{"a":"atlab_sokka","t":"Je vais réparer notre équipement en un rien de temps !"},{"a":"blacksmith","t":"Cette épée que tu affûtes... où l’as-tu dénichée ?"},{"a":"atlab_sokka","t":"C’est mon épée spatiale. Je l’ai forgée moi-même !"},{"a":"blacksmith","t":"Du minerai de météorite ? Décidément, tu m’impressionnes."},{"a":"blacksmith","t":"Elle doit être d’une puissance... astronomique !"},{"a":"atlab_sokka","t":"Carrément ! Aucune autre épée ne lui arrive à la cheville."},{"a":"polonia","t":"Ohé ! Pardon de vous interrompre, mais y aurait-il un bon gars pour m’aider à calfater mon bateau ?"},{"a":"polonia","t":"Il est très capricieux aujourd’hui. Il a touché d’étranges boulets de fer et s’est retrouvé échoué..."},{"a":"blacksmith","t":"En effet, pas de quoi se marée !"},{"a":"atlab_sokka","t":"Pas de problème, je suis de la Tribu de l’Eau ! Je vais voir ce que je peux faire. Désolé, Wallace, je dois filer !"},{"a":"blacksmith","t":"Je vais réparer le restant de ton équipement en attendant. Bon courage !"}]},{"id":"atlab_sokka_03","i":3,"title":"Sokka le grand navigateur","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"atlab_sokka","t":"Voilà, vous devriez pouvoir rentrer à bon port, minimum."},{"a":"polonia","t":"Tu l’as rudement bien radoubé, dis donc !"},{"a":"atlab_sokka","t":"... Votre gouvernail est maintenu par du bois flotté et quelques bouts de ma chemise."},{"a":"atlab_sokka","t":"Radoubé, c’est un bien grand mot. Rafistolé, disons."},{"a":"polonia","t":"Yo ho ho ! Comment se fait-il qu’un marin d’eau douce comme toi sache réparer des bateaux ?"},{"a":"atlab_sokka","t":"Dans les Tribus de l’Eau, les bateaux et la pêche sont notre quotidien. Je prenais la mer avant de savoir marcher."},{"a":"atlab_sokka","t":"Tout récemment, j’ai même conçu un sous-marin propulsé par la maîtrise de l’eau !"},{"a":"polonia","t":"Là, tu m’as larguée par-dessus bord. De quoi tu parles ?"},{"a":"atlab_sokka","t":"D’un... bateau en métal qui va sous l’eau."},{"a":"polonia","t":"Mouais. Ça m’a tout l’air d’un bon moyen pour finir ses jours au fond de l’océan."},{"a":"engineer","t":"Ai-je bien entendu \"très dangereux prototype non testé\" ?"},{"a":"atlab_sokka","t":"Euh... Pas tout à fait."},{"a":"engineer","t":"Toi, je t’aime bien. Viens avec moi, le nouveau."},{"a":"polonia","t":"Yo ho ho, retour en mer ! Larguez les amarres, avant que les chasseurs de primes ne débarquent ici !"},{"a":"polonia","t":"Cette fois, j’ai intérêt à louvoyer entre les boulets de fer flottants."}]},{"id":"atlab_sokka_04","i":4,"title":"Sokka le grand inventeur","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"engineer","t":"Fascinant ! Je ne vais pas te mentir, ton plan est un peu brouillon..."},{"a":"engineer","t":"Mais avec un peu d’huile de coude, ce sous-marin doit pouvoir marcher !"},{"a":"atlab_sokka","t":"Génial, pas vrai ? Je le savais !"},{"a":"atlab_sokka","t":"Attention quand même, il est conçu pour être actionné par des maîtres de l’eau."},{"a":"engineer","t":"C’est un détail. On trouvera bien une solution."},{"a":"engineer","t":"Imagine ! Avec ça, on pourrait explorer le Temple immergé !"},{"a":"atlab_sokka","t":"Et la réserve d’air est limitée, alors évitez les longs trajets."},{"a":"atlab_sokka","t":"... Dites, vous m’écoutez ?"},{"a":"engineer","t":"Ne t’appuie pas sur ce grand boulet de fer."},{"a":"atlab_sokka","t":"Hein ? Holà ! Pourquoi ça ?"},{"a":"engineer","t":"C’est mon prototype de mine marine. N’y touche pas. Un rien et il explose."},{"a":"atlab_sokka","t":"... Oh."},{"a":"atlab_sokka","t":"Enfin bref, tenez-moi au courant pour le sous-marin."},{"a":"atlab_sokka","t":"Si ça fonctionne... il nous sera utile par la suite."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Hé, salut. Je crois que j’en ai assez d’être champion."},{"a":"leather","t":"C’est beaucoup plus de responsabilités que je pensais. Je délaisse limite mon cuir !"},{"a":"leather","t":"Je réessaierai peut-être l’année prochaine. À plus tard dans le coin !"}]},{"id":"leather_01","i":1,"title":"Le cuir et l’arbre","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"leather","t":"Merci pour l’aide."},{"a":"argon","t":"De rien, Tamas ! Ça fait un sacré tas de cuir !"},{"a":"leather","t":"J’ai eu une grosse récolte aujourd’hui. Attention par terre, hein."},{"a":"argon","t":"Oui... C’est vrai que c’est accidenté par ici. Ouaaah !"},{"a":"leather","t":"Ho ! Aïe !"},{"a":"argon","t":"Désolé, Tamas ! Tout va bien ?"},{"a":"leather","t":"Je me suis un peu cogné la tête. Je crois que ça va."},{"a":"leather","t":"Mec... Je viens d’avoir un éclair de génie."},{"a":"leather","t":"Je dois y aller. Ça va être du lourd."},{"a":"argon","t":"Pas de problème ! Ravi d’avoir pu aider !"},{"a":"argon","t":"Mais euh... Qu’est-ce que je vais faire de tout ce cuir ?"}]},{"id":"leather_02","i":2,"title":"Comme l’annonçait la prophétie","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"leather","t":"(...) Et c’est comme ça que je me suis cogné la tête. J’ai une petite bosse."},{"a":"mana","t":"Elle vous écoute, mais ne peut point aider."},{"a":"mana","t":"Le flot de l’éther annonce, il devine et révèle, mais il ne soigne pas."},{"a":"leather","t":"Mais c’est de la magie, non ? Allez, y a juste à me toucher la tête avec vos mains magiques."},{"a":"mana","t":"Il n’y a nulle..."},{"a":"mana","t":"!!!"},{"a":"mana","t":"Une... destinée... Trop de..."},{"a":"leather","t":"Z’êtes sûre que ça a marché ? Je suis encore un peu dans les vapes."},{"a":"mana","t":"Mes excuses. Une vision m’est venue et je dois y méditer."},{"a":"mana","t":"Pour vos... blessures, allez demander la faveur de la déesse. Je dois partir sur-le-champ."},{"a":"leather","t":"Bon. Ça roule. Je vais attendre que ça passe, je me sens bien en forme ces temps-ci."}]},{"id":"leather_03","i":3,"title":"Le syndicat des champions","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"argon","t":"Et donc, euh. Il y a un nouveau champion dans la cité."},{"a":"polonia","t":"Yo ho ho ! J’espère qu’il est bien musclé !"},{"a":"leather","t":"Salut la compagnie."},{"a":"polonia","t":"Nom d’une bernicle, mais vous plaisantez ?!"},{"a":"lilu","t":"Tamas ?! Quand est-ce que..."},{"a":"leather","t":"J’ai décidé d’essayer de faire champion un peu. Ça a pas l’air très compliqué."},{"a":"argon","t":"Hum. Cher Tamas, et si tu nous parlais de tes talents ?"},{"a":"leather","t":"Ben, je file des coups aux monstres. Et aussi, je sens les objets en cuir à des kilomètres."},{"a":"polonia","t":"Ohé ! Voler les objets, c’est mon truc à moi ! Trouve-toi autre chose !"},{"a":"leather","t":"C’est pas du vol. Les gens les laissent traîner partout, c’est tout."},{"a":"lilu","t":"Je crois que les choses prennent une tournure intéressante..."},{"a":"polonia","t":"Har, t’as peut-être bien raison..."}]},{"id":"leather_04","i":4,"title":"Un héros inconnu","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Jetons de fortune"},"side":false,"lines":[{"a":"sia","t":"Sire, j’apporte des nouvelles inhabituelles."},{"a":"king","t":"Je suis tout ouïe, comme toujours !"},{"a":"sia","t":"Nos héros et caravanes nous font savoir que les routes sont plus sûres que jamais."},{"a":"sia","t":"Les monstres se terrent et semblent même avoir peur de s’en prendre à quiconque."},{"a":"king","t":"Splendides nouvelles !"},{"a":"sia","t":"Mais nous ne voyons aucune explication à cet étrange comportement."},{"a":"sia","t":"Et tout aussi étrange : le marché des biens en cuir s’est subitement effondré."},{"a":"king","t":"Une simple coïncidence, assurément ! Organisons un festin pour célébrer ces nouvelles !"},{"a":"sia","t":"Peut-être bien, sire. Peut-être bien."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"L’Azumane errante","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Hi hi hi, mais qu’avons-nous là ?"},{"a":"yami","t":"Humpf. Du vent, vermine."},{"a":"monster_forest_Boss","t":"T’es mal élevée, m’dame ! Et bizarrement habillée."},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Hi hi, mais tu portes l’odeur d’Azuma, le royaume humain de l’est !"},{"a":"monster_forest_Boss","t":"Qu’est-ce que tu fais si loin de chez toi, m’dame ?"},{"a":"monster_forest_Boss","t":"Armée jusqu’aux dents et muette comme une tombe. T’es un assassin, c’est ça ?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Hi hi hi, je le savais ! Ces idiots d’humains qui passent leur temps à se flinguer entre eux."},{"a":"yami","t":"C’est vrai... Je suis venue jusqu’ici pour tuer un tyran."},{"a":"monster_forest_Boss","t":"Hé ! Tu fais pas un très bon assassin si tu racontes ça à tout le monde. Pourquoi tu me l’as dit ?"},{"a":"yami","t":"Parce que tu ne seras plus là pour en parler à personne. Adieu."},{"a":"monster_forest_Boss","t":"Iiiik !"},{"a":"yami","t":"Reinhold... tu seras le prochain."}]},{"id":"yami_02","i":2,"title":"Chasser ou être chassé","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"yami","t":"Le château est très bien gardé."},{"a":"yami","t":"Ils changent le mot de passe tous les jours..."},{"a":"yami","t":"Il font des patrouilles à l’improviste..."},{"a":"yami","t":"Je vais devoir..."},{"a":"argon","t":"Oh, bonjour ! Oui, toi là, dans les buissons, bonjour !"},{"a":"yami","t":"!!"},{"a":"argon","t":"Toi aussi, tu veux devenir chevalier ?"},{"a":"argon","t":"Sia ne va pas tarder ! Pas la peine de te cacher, elle est très gentille."},{"a":"yami","t":"Sia !"},{"a":"yami","t":"Il faut que j’y aille. Au revoir."},{"a":"argon","t":"Mais, attendez !"},{"a":"argon","t":"Ouah ! Une bombe fumigène ?!"},{"a":"yami","t":"Ça va, j’ai semé l’autre idiot."},{"a":"yami","t":"Si Sia est ici... ça ne va pas être facile."},{"a":"yami","t":"Mais je dois y arriver, il le faut."},{"a":"yami","t":"Pour l’ordre... Et pour ma sœur."}]},{"id":"yami_03","i":3,"title":"Le tournant","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"king","t":"Très cher peuple de mon royaume ! Merci d'être venu si nombreux à cette fête somptueuse !"},{"a":"king","t":"C'est également l'occasion parfaite pour vous tous de baigner dans la magnifique aura de ma présence ! Ne ratez pas cette occasion et cette chance exceptionnelle !"},{"a":"yami","t":"(Pompeux et tyrannique. Je ne suis même pas étonnée.)"},{"a":"sia","t":"Euh, oui. Merci pour ce discours édifiant, votre majesté."},{"a":"sia","t":"Si nous sommes réunis ici aujourd'hui, c'est pour célébrer l'incroyable générosité de notre roi."},{"a":"sia","t":"Ces derniers mois, il a donné plusieurs millions de pièces d'or de ses propres coffres..."},{"a":"sia","t":"...à plusieurs temples, écoles et orphelinats du coin."},{"a":"sia","t":"Vous êtes tous autant que vous êtes les bienvenus à cette fête, alors dites-le à vos amis et à votre famille."},{"a":"sia","t":"Longue vie au roi Reinhold !"},{"a":"yami","t":"(... Ces actions ne ressemblent pas à celle d'un tyran.)"},{"a":"yami","t":"(... Non, l'ordre ne mentirait pas. C'est sûrement une ruse.)"},{"a":"yami","t":"Reinhold, espèce de tyran ! Ton règne se termine sans plus tarder !"},{"a":"sia","t":"Un shuriken... ! Cet assassin, cette espionne azumane !"},{"a":"yami","t":"J'ai raté... !? Impossible !"},{"a":"sia","t":"Gardes ! Bloquez toutes les sorties ! Arrêtez cette femme et vite !"}]},{"id":"yami_04","i":4,"title":"Réflexion","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"yami","t":"(J'ai hésité... Et échoué.)"},{"a":"yami","t":"(Est-ce que l'ordre aurait pu mentir... ?)"},{"a":"yami","t":"(Peu importe. Désormais, je ne peux compter que sur moi-même.)"},{"a":"argon","t":"Ah, enfin, te voilà !"},{"a":"yami","t":"Cet imbécile de chevalier !"},{"a":"argon","t":"Waouh ! Je ne suis pas là pour me battre !"},{"a":"yami","t":"Je ne tomberai pas dans ton piège, chien de Reinhold !"},{"a":"argon","t":"... Tu as fait exprès de rater, c'est ça ?"},{"a":"yami","t":"... !"},{"a":"argon","t":"Je t'ai vue à la fête. On aurait même dit que tu regrettais d'avoir lancé ce shuriken."},{"a":"argon","t":"Le roi n'est pas un mauvais bougre. D'accord, il est bizarre parfois, mais il fait toujours de son mieux !"},{"a":"argon","t":"Je ne sais pas qui t'a payée pour faire ça, mais ça ne peut pas être des types sympas..."},{"a":"argon","t":"Et si tu retournais au château pour t'excuser ? Je parie que Reinhold..."},{"a":"yami","t":"...M'excuser ? Quelle idée vraiment débile !"},{"a":"yami","t":"J'ai à réfléchir. Ne me suis pas, si tu tiens à la vie."},{"a":"argon","t":"... Ce n'est pas une mauvaise fille, j'en suis sûr."},{"a":"argon","t":"Maintenant, je dois faire mon rapport à Sia..."},{"a":"argon","t":"Oh là là, elle ne va pas être contente..."}]},{"id":"yami_05","i":5,"title":"Au clair de lune","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Le soleil dans les saules, éclat du temps jadis...<sprite tint=1 name=Note2>"},{"a":"fabric","t":"<sprite tint=1 name=Note2>Nous fils des clairières, nous... Hiii !"},{"a":"yami","t":"Cette froide piqûre que tu sens, c’est ma lame sur ta nuque."},{"a":"yami","t":"J’ai des questions. Dis la vérité et je te laisserai peut-être la vie sauve."},{"a":"fabric","t":"Haaaa ! Oui, je ferai tout c... Aïe !"},{"a":"yami","t":"Silence."},{"a":"yami","t":"Cet idiot que vous appelez votre roi. Parle-moi de lui."},{"a":"fabric","t":"Reinhold ? C’est lui qui dirige le royaume."},{"a":"fabric","t":"Il est assez excentrique, mais personne ne peut nier sa droiture et sa générosité."},{"a":"fabric","t":"Il manque d’expérience, mais sa nouvelle conseillère Sia compense largement de ce côté-là."},{"a":"yami","t":"Impossible ! Pourtant... Tes paroles puent la peur, mais tu n’as pas l’air de mentir."},{"a":"yami","t":"Est-ce qu’il y a un oracle dans la cité ?"},{"a":"fabric","t":"Euh, oui ! L’elfe Sérène, sur la colline !"},{"a":"fabric","t":"Dites-moi, mystérieuse inconnue, pourrais-je avoir l’honneur de connaître votre n... Aïe !"},{"a":"yami","t":"Il y a encore quelques jours, je n’aurais pas hésité un instant à te tuer. Ne force pas ta chance."},{"a":"yami","t":"Retourne à ta vie insipide et oublie tout ce qui s’est passé ici."},{"a":"fabric","t":"Pfiouh ! Quelle rencontre exaltante !"},{"a":"fabric","t":"Ô jeune femme de noir vêtue, nous reverrons-nous un jour ?"}]},{"id":"yami_06","i":6,"title":"Un pion perdu","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"mana","t":"Une brise noire vient trahir la présence de Celle Qui Traque..."},{"a":"yami","t":"Mais ?! Comment ?"},{"a":"mana","t":"Celle Qui Traque a le pas d’une plume, mais le poids d’un cœur lourd n’échappe pas au troisième œil."},{"a":"yami","t":"Fini les devinettes, oracle. Il me faut des réponses."},{"a":"yami","t":"Sur l’ordre... Et sur ma famille."},{"a":"mana","t":"Une porteuse de mort vient implorer conseil. Qu’offre-t-elle en retour ?"},{"a":"yami","t":"Ta vie."},{"a":"mana","t":"Qu’il en soit ainsi."},{"a":"mana","t":"<c1>L’Ordre azuman, autrefois fléau de l’injustice</c1>"},{"a":"mana","t":"<c1>Les défenseurs de l’équité devenus esclaves du plus offrant</c1>"},{"a":"mana","t":"<c1>Face à un impossible dessein, un pion est sacrifié</c1>"},{"a":"mana","t":"<c1>Vienne la réussite ou l’échec, l’ordre sera gagnant</c1>"},{"a":"yami","t":"Impossible..."},{"a":"mana","t":"La messagère a parlé."},{"a":"yami","t":"IMPOSSIBLE !"},{"a":"mana","t":"..."},{"a":"mana","t":"Quiconque évolue dans l’ombre doit un jour payer son dû à la lumière."}]},{"id":"yami_07","i":7,"title":"Un pion perdu","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"yami","t":"Il faut que je rassemble mes affaires pour partir le plus vite possible."},{"a":"inn","t":"Hé, bonjour, chère mystérieuse inconnue."},{"a":"yami","t":"L’aubergiste. J’ai acheté votre discrétion, déjà."},{"a":"inn","t":"Ne vous en faites pas. Ici, à l’auberge de l’Émeraude, on n’est pas du genre fouineurs."},{"a":"inn","t":"Ceci étant dit, il y a eu de nouveaux clients qui n’avaient pas l’air commode et qui semblaient en avoir après vous."},{"a":"yami","t":"(Des agents de l’ordre... Déjà ?)"},{"a":"inn","t":"Ils n’ont pas laissé de nom. Ils avaient l’air vraiment louche. Des amis à vous, peut-être ?"},{"a":"yami","t":"Plus maintenant. Dites-leur que je suis morte... ça ne fera pas une grande différence."},{"a":"inn","t":"Pressée de nous quitter ? Je m’en doutais un peu, je vous ai préparé quelques provisions."},{"a":"yami","t":"Merci... Mais là où je vais, je n’en aurai pas besoin."}]},{"id":"yami_08","i":8,"title":"Aller simple","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Vers le pic de Morneflèche, hein ?"},{"a":"wood","t":"Ouais. Une fille habillée en ninja comme vous aviez décrit. Elle avait l’air pressée."},{"a":"sia","t":"Excellent. Nous tenons enfin notre assassin."},{"a":"sia","t":"Je vais envoyer une patrouille et..."},{"a":"wood","t":"Vous pensez ? Ça ne me paraît pas nécessaire."},{"a":"sia","t":"Ah. Et pourquoi donc ?"},{"a":"wood","t":"Une expédition en solo au pic de Morneflèche, c’est un suicide. Elle n’avait même pas de sac de provisions."},{"a":"wood","t":"Elle savait forcément à quoi elle s’exposait. Même Rudo n’est pas assez idiot pour partir là-bas tout seul."},{"a":"sia","t":"Vraiment ? Merci, Gorza. Je vais prendre ça en considération."},{"a":"sia","t":"On dirait que le problème va se résoudre de lui-même, mais..."},{"a":"sia","t":"Ça me laisse un goût amer. Petit assassin... qu’as-tu donc en tête ?"}]},{"id":"yami_09","i":9,"title":"Choc de Morneflèche (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"argon","t":"C’est un signe du destin... une proie encore plus glorieuse qu’une harpie !"},{"a":"yami","t":"Essaie un peu. Si tu bouges, je t’exécute."},{"a":"argon","t":"Tu dis ça, mais tu n’as pas vraiment l’air d’y croire."},{"a":"yami","t":"C’est vrai... Plus rien n’a d’importance, de toute façon."},{"a":"yami","t":"Si tu veux vraiment ma mort, tu n’as qu’à m’abandonner ici."},{"a":"argon","t":"Je ne laisserai jamais personne mourir ! Je vais t’amener au sire Reinhold."},{"a":"argon","t":"Je sais qu’il comprendra ! Je vais te porter sur mon dos s’il le faut !"},{"a":"yami","t":"..."},{"a":"argon","t":"Allez, hop !"},{"a":"argon","t":"Oh, mais tu n’as plus que la peau sur les os ! Depuis quand tu n’as pas mangé ?"},{"a":"yami","t":"..."},{"a":"argon","t":"Grignote quelque chose pour le chemin, ça va secouer un peu !"}]},{"id":"yami_10","i":10,"title":"Derrière les lignes ennemies","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Gardes ! Faites venir des renforts, et restez à l’affût du moindre geste !"},{"a":"sia","t":"Argon, je vous prie d’attendre dehors pendant que nous interrogeons... l’intruse."},{"a":"argon","t":"À vos ordres !"},{"a":"sia","t":"Alors. Nous t’écoutons, assassins."},{"a":"yami","t":"Humpf, c’est le bon mot. On m’a engagée pour assassiner un tyran."},{"a":"yami","t":"Enfin, je le croyais. Mais on dirait que c’est juste un guignol farci de bonnes intentions."},{"a":"king","t":"Un guignol ?!!"},{"a":"sia","t":"Et qu’avez-vous contre notre roi, vous et les vôtres ?"},{"a":"yami","t":"Mon ordre ne frappe jamais qu’au nom de la justice..."},{"a":"yami","t":"Mais on dirait que tout ça n’était que mensonges. Et de toute façon, mon échec a fait de moi une proie."},{"a":"yami","t":"Je... Je suis désolée. J’accepterai le... juste... châtiment..."},{"a":"yami","t":"Ourgh."},{"a":"king","t":"Elle a perdu connaissance !"},{"a":"sia","t":"Elle est affamée et à bout de forces."},{"a":"sia","t":"Gardes ! Qu’on envoie les médecins royaux à son chevet !"},{"a":"sia","t":"Et qu’on la traite avec le respect dû aux invités du roi."}]},{"id":"yami_epilogue","i":11,"title":"Épilogue","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyaux"},"side":false,"lines":[{"a":"sia","t":"Ffff... Ffff... sacrée escalade... pour arriver ici..."},{"a":"yami","t":"C’est ici que je vis, maintenant."},{"a":"sia","t":"Pourquoi ne pas vous installer dans la cité ? Vous avez reçu un pardon officiel."},{"a":"yami","t":"Mon clan doit me croire morte. Je préférerais qu’il continue."},{"a":"sia","t":"Je comprends. Je ferai envoyer des provisions régulièrement."},{"a":"sia","t":"Mais parlons de votre prochaine mission..."},{"a":"yami","t":"Encore des sbires de l’empire ?"},{"a":"sia","t":"Oui. Comme vous le savez, sa Majesté fait bien des envieux."},{"a":"sia","t":"Prenez ce document, il y a toutes les informations sur les cibles."},{"a":"yami","t":"Ce sera fait."},{"a":"sia","t":"Je crains fort de ne pas en douter."},{"a":"sia","t":"Il faut que je rentre. Même si refaire le trajet en sens inverse ne m’enchante pas..."},{"a":"yami","t":"Sia... Reinhold..."},{"a":"yami","t":"Très sincèrement, merci."}]}]}];
